  public static bool StartRoomCheck(int x, int y, IRoomCheckFeedback feedback = null)
  {
    if (feedback == null)
      feedback = (IRoomCheckFeedback) NoRoomCheckFeedback.WithText;
    WorldGen.roomHasStinkbug = false;
    WorldGen.roomHasEchoStinkbug = false;
    WorldGen.roomX1 = x;
    WorldGen.roomX2 = x;
    WorldGen.roomY1 = y;
    WorldGen.roomY2 = y;
    WorldGen.roomTiles.Reset(new Point(x, y), WorldGen.maxRoomSize);
    WorldGen.numRoomTiles = 0;
    for (int index = 0; index < (int) TileID.Count; ++index)
      WorldGen.houseTile[index] = false;
    WorldGen.canSpawn = true;
    if (Main.tile[x, y].nactive() && Main.tileSolid[(int) Main.tile[x, y].type])
    {
      feedback.StartedInASolidTile(x, y);
      WorldGen.roomCheckFailureReason = TownNPCRoomCheckFailureReason.RoomCheckStartedInASolidTile;
      WorldGen.canSpawn = false;
      return false;
    }
    WorldGen.roomCheckFailureReason = TownNPCRoomCheckFailureReason.None;
    Stack<Point> roomCheckStack = WorldGen._roomCheckStack;
    roomCheckStack.Clear();
    roomCheckStack.Push(new Point(x, y));
    while (roomCheckStack.Count > 0 && (WorldGen.canSpawn || !feedback.StopOnFail))
    {
      Point point = roomCheckStack.Pop();
      if (WorldGen.CheckRoom(point.X, point.Y, roomCheckStack.Count, feedback))
      {
        for (int index1 = -1; index1 <= 1; ++index1)
        {
          for (int index2 = -1; index2 <= 1; ++index2)
          {
            if (index1 != 0 || index2 != 0)
              roomCheckStack.Push(new Point(point.X + index1, point.Y + index2));
          }
        }
      }
    }
    if (!WorldGen.canSpawn)
      return false;
    if (WorldGen.numRoomTiles < 60)
    {
      WorldGen.roomCheckFailureReason = TownNPCRoomCheckFailureReason.RoomIsTooSmall;
      WorldGen.canSpawn = false;
      return false;
    }
    return WorldGen.canSpawn;
  }

  private static bool CheckRoom(int x, int y, int iteration, IRoomCheckFeedback feedback)
  {
    bool stopOnFail = feedback.StopOnFail;
    if (x < 10 || y < 10 || x >= Main.maxTilesX - 10 || y >= WorldGen.lastMaxTilesY - 10)
    {
      feedback.TooCloseToWorldEdge(x, y, iteration);
      WorldGen.roomCheckFailureReason = TownNPCRoomCheckFailureReason.TooCloseToWorldEdge;
      WorldGen.canSpawn = false;
      return false;
    }
    if (!WorldGen.roomTiles.InBounds(new Point(x, y)))
    {
      feedback.RoomTooBig(x, y, iteration);
      WorldGen.roomCheckFailureReason = TownNPCRoomCheckFailureReason.RoomIsTooBig;
      WorldGen.canSpawn = false;
      return false;
    }
    if (!WorldGen.roomTiles.Add(new Point(x, y)))
      return false;
    ++WorldGen.numRoomTiles;
    if (stopOnFail && WorldGen.numRoomTiles >= WorldGen.maxRoomTiles)
    {
      feedback.RoomTooBig(x, y, iteration);
      WorldGen.roomCheckFailureReason = TownNPCRoomCheckFailureReason.RoomIsTooBig;
      WorldGen.canSpawn = false;
      return false;
    }
    if (x < WorldGen.roomX1)
      WorldGen.roomX1 = x;
    if (x > WorldGen.roomX2)
      WorldGen.roomX2 = x;
    if (y < WorldGen.roomY1)
      WorldGen.roomY1 = y;
    if (y > WorldGen.roomY2)
      WorldGen.roomY2 = y;
    if (stopOnFail && (WorldGen.roomX2 - WorldGen.roomX1 >= WorldGen.maxRoomSize || WorldGen.roomY2 - WorldGen.roomY1 >= WorldGen.maxRoomSize))
    {
      feedback.RoomTooBig(x, y, iteration);
      WorldGen.roomCheckFailureReason = TownNPCRoomCheckFailureReason.RoomIsTooBig;
      WorldGen.canSpawn = false;
      return false;
    }
    feedback.AnyBlockScannedHere(x, y, iteration);
    if (Main.tile[x, y].nactive())
    {
      WorldGen.houseTile[(int) Main.tile[x, y].type] = true;
      if (Main.tileSolid[(int) Main.tile[x, y].type])
      {
        feedback.BlockingWall(x, y, iteration);
        return false;
      }
      if (Main.tile[x, y].type == (ushort) 11 && (Main.tile[x, y].frameX == (short) 0 || Main.tile[x, y].frameX == (short) 54 || Main.tile[x, y].frameX == (short) 72 || Main.tile[x, y].frameX == (short) 126))
      {
        feedback.BlockingOpenGate(x, y, iteration);
        return false;
      }
      if (Main.tile[x, y].type == (ushort) 389)
      {
        feedback.BlockingOpenGate(x, y, iteration);
        return false;
      }
      if (Main.tile[x, y].type == (ushort) 386 && (Main.tile[x, y].frameX < (short) 36 && Main.tile[x, y].frameY == (short) 18 || Main.tile[x, y].frameX >= (short) 36 && Main.tile[x, y].frameY == (short) 0))
      {
        feedback.BlockingOpenGate(x, y, iteration);
        return false;
      }
      if (Main.tile[x, y].type == (ushort) 630)
      {
        WorldGen.roomHasStinkbug = true;
        feedback.Stinkbug(x, y, iteration);
      }
      if (Main.tile[x, y].type == (ushort) 631)
      {
        WorldGen.roomHasEchoStinkbug = true;
        feedback.EchoStinkbug(x, y, iteration);
      }
    }
    bool flag1 = false;
    bool flag2 = false;
    for (int index = -2; index < 3; ++index)
    {
      if (Main.wallHouse[(int) Main.tile[x + index, y].wall])
        flag1 = true;
      if (Main.tile[x + index, y].nactive() && (Main.tileSolid[(int) Main.tile[x + index, y].type] || TileID.Sets.HousingWalls[(int) Main.tile[x + index, y].type]))
        flag1 = true;
      if (Main.wallHouse[(int) Main.tile[x, y + index].wall])
        flag2 = true;
      if (Main.tile[x, y + index].nactive() && (Main.tileSolid[(int) Main.tile[x, y + index].type] || TileID.Sets.HousingWalls[(int) Main.tile[x, y + index].type]))
        flag2 = true;
    }
    if (flag1 && flag2)
      return true;
    if (Main.tile[x, y].wall > (ushort) 0)
    {
      feedback.UnsafeWall(x, y, iteration);
      WorldGen.roomCheckFailureReason = TownNPCRoomCheckFailureReason.TooManyUnsafeWalls;
    }
    else
    {
      feedback.MissingAWall(x, y, iteration);
      WorldGen.roomCheckFailureReason = TownNPCRoomCheckFailureReason.HoleInWallIsTooBig;
    }
    WorldGen.canSpawn = false;
    return false;
  }

