  public static bool dropMeteor(bool spawnUnderGround = false)
  {
    bool flag = true;
    if (!WorldGen.isGeneratingOrLoadingWorld)
    {
      if (Main.netMode == 1 || !Main.isThereAWorldSurface)
        return false;
      for (int index = 0; index < (int) byte.MaxValue; ++index)
      {
        if (Main.player[index].active)
        {
          flag = false;
          break;
        }
      }
    }
    else
      flag = false;
    if (!WorldGen.isGeneratingOrLoadingWorld)
    {
      int num1 = 0;
      int num2 = (int) (400.0 * ((double) Main.maxTilesX / 4200.0));
      for (int index1 = 5; index1 < Main.maxTilesX - 5; ++index1)
      {
        for (int index2 = 5; (double) index2 < Main.worldSurface; ++index2)
        {
          if (Main.tile[index1, index2].active() && Main.tile[index1, index2].type == (ushort) 37)
          {
            ++num1;
            if (num1 > num2)
              return false;
          }
        }
      }
    }
    double num3 = 600.0;
    int num4 = 0;
    int num5 = (int) (Main.worldSurface * 0.3);
    if (spawnUnderGround)
      num5 = WorldGen.genRand.Next((int) (Main.worldSurface + Main.rockLayer) / 2, Main.UnderworldLayer);
    while (!flag)
    {
      double num6 = (double) Main.maxTilesX * 0.08;
      int index3 = Main.rand.Next(150, Main.maxTilesX - 150);
      while ((double) index3 > (double) Main.spawnTileX - num6 && (double) index3 < (double) Main.spawnTileX + num6)
        index3 = Main.rand.Next(150, Main.maxTilesX - 150);
      for (int index4 = num5; index4 < Main.maxTilesY; ++index4)
      {
        if (WorldGen.InWorld(index3, index4, 2))
        {
          Tile tile1 = Main.tile[index3, index4];
          if (tile1.active() && Main.tileSolid[(int) tile1.type] && !TileID.Sets.Platforms[(int) tile1.type])
          {
            int num7 = 0;
            int num8 = 15;
            for (int index5 = index3 - num8; index5 < index3 + num8; ++index5)
            {
              for (int index6 = index4 - num8; index6 < index4 + num8; ++index6)
              {
                if (WorldGen.InWorld(index5, index6, 2))
                {
                  if (WorldGen.SolidTile(index5, index6))
                  {
                    Tile tile2 = Main.tile[index5, index6];
                    ++num7;
                    if (tile2.type >= (ushort) 0 && TileID.Sets.Clouds[(int) tile2.type] || tile2.type == (ushort) 202)
                      num7 -= 100;
                  }
                  else if (Main.tile[index5, index6].liquid > (byte) 0)
                    --num7;
                }
              }
            }
            if ((double) num7 >= num3)
            {
              flag = WorldGen.meteor(index3, index4);
              if (flag)
                return flag;
              break;
            }
            num3 -= 0.5;
            break;
          }
        }
      }
      ++num4;
      if (num3 < 100.0 || num4 >= Main.maxTilesX * 5)
        return false;
    }
    return false;
  }

  public static bool meteor(int i, int j, bool ignorePlayers = false)
  {
    if (i < 50 || i > Main.maxTilesX - 50 || j < 50 || j > Main.maxTilesY - 50)
      return false;
    int num1 = 35;
    int centeredSquareSize = num1 * 2 + 5;
    Microsoft.Xna.Framework.Rectangle rectangle1 = new Microsoft.Xna.Framework.Rectangle((i - num1) * 16 /*0x10*/, (j - num1) * 16 /*0x10*/, num1 * 2 * 16 /*0x10*/, num1 * 2 * 16 /*0x10*/);
    if (!WorldGen.InWorld(i - num1, j - num1, 10) || !WorldGen.InWorld(i + num1, j + num1, 10))
      return false;
    for (int index = 0; index < (int) byte.MaxValue; ++index)
    {
      if (Main.player[index].active && !ignorePlayers)
      {
        Microsoft.Xna.Framework.Rectangle rectangle2 = new Microsoft.Xna.Framework.Rectangle((int) ((double) Main.player[index].position.X + (double) (Main.player[index].width / 2) - (double) (NPC.sWidth / 2) - (double) NPC.safeRangeX), (int) ((double) Main.player[index].position.Y + (double) (Main.player[index].height / 2) - (double) (NPC.sHeight / 2) - (double) NPC.safeRangeY), NPC.sWidth + NPC.safeRangeX * 2, NPC.sHeight + NPC.safeRangeY * 2);
        if (rectangle1.Intersects(rectangle2))
          return false;
      }
    }
    for (int index = 0; index < Main.maxNPCs; ++index)
    {
      if (Main.npc[index].active)
      {
        Microsoft.Xna.Framework.Rectangle rectangle3 = new Microsoft.Xna.Framework.Rectangle((int) Main.npc[index].position.X, (int) Main.npc[index].position.Y, Main.npc[index].width, Main.npc[index].height);
        if (rectangle1.Intersects(rectangle3))
          return false;
      }
    }
    for (int index1 = i - num1; index1 < i + num1; ++index1)
    {
      for (int index2 = j - num1; index2 < j + num1; ++index2)
      {
        if (Main.tile[index1, index2].active())
        {
          if (TileID.Sets.BasicChest[(int) Main.tile[index1, index2].type] || Main.tileDungeon[(int) Main.tile[index1, index2].type])
            return false;
          switch (Main.tile[index1, index2].type)
          {
            case 26:
            case 226:
            case 470:
            case 475:
            case 488:
            case 597:
              return false;
            default:
              continue;
          }
        }
      }
    }
    WorldGen.stopDrops = true;
    int num2 = WorldGen.genRand.Next(17, 23);
    for (int x = i - num2; x < i + num2; ++x)
    {
      for (int y = j - num2; y < j + num2; ++y)
      {
        if (y > j + Main.rand.Next(-2, 3) - 5)
        {
          double num3 = (double) Math.Abs(i - x);
          double num4 = (double) Math.Abs(j - y);
          if (Math.Sqrt(num3 * num3 + num4 * num4) < (double) num2 * 0.9 + (double) Main.rand.Next(-4, 5))
          {
            if (!Main.tileSolid[(int) Main.tile[x, y].type])
              Main.tile[x, y].active(false);
            WorldGen.paintTile(x, y, (byte) 0, Main.netMode == 2, false);
            WorldGen.paintCoatTile(x, y, (byte) 0, Main.netMode == 2, false);
            Main.tile[x, y].ClearSlope();
            Main.tile[x, y].type = (ushort) 37;
          }
        }
      }
    }
    int num5 = WorldGen.genRand.Next(8, 14);
    for (int index3 = i - num5; index3 < i + num5; ++index3)
    {
      for (int index4 = j - num5; index4 < j + num5; ++index4)
      {
        if (index4 > j + Main.rand.Next(-2, 3) - 4)
        {
          double num6 = (double) Math.Abs(i - index3);
          double num7 = (double) Math.Abs(j - index4);
          if (Math.Sqrt(num6 * num6 + num7 * num7) < (double) num5 * 0.8 + (double) Main.rand.Next(-3, 4))
            Main.tile[index3, index4].active(false);
        }
      }
    }
    int num8 = WorldGen.genRand.Next(25, 35);
    for (int i1 = i - num8; i1 < i + num8; ++i1)
    {
      for (int j1 = j - num8; j1 < j + num8; ++j1)
      {
        double num9 = (double) Math.Abs(i - i1);
        double num10 = (double) Math.Abs(j - j1);
        if (Math.Sqrt(num9 * num9 + num10 * num10) < (double) num8 * 0.7)
        {
          if (TileID.Sets.GetsDestroyedForMeteors[(int) Main.tile[i1, j1].type])
            WorldGen.KillTile(i1, j1);
          Main.tile[i1, j1].liquid = (byte) 0;
        }
        if (Main.tile[i1, j1].type == (ushort) 37)
        {
          if (!WorldGen.SolidTile(i1 - 1, j1) && !WorldGen.SolidTile(i1 + 1, j1) && !WorldGen.SolidTile(i1, j1 - 1) && !WorldGen.SolidTile(i1, j1 + 1))
            Main.tile[i1, j1].active(false);
          else if ((Main.tile[i1, j1].halfBrick() || Main.tile[i1 - 1, j1].topSlope()) && !WorldGen.SolidTile(i1, j1 + 1))
            Main.tile[i1, j1].active(false);
        }
        WorldGen.SquareTileFrame(i1, j1);
        WorldGen.SquareWallFrame(i1, j1);
      }
    }
    int num11 = WorldGen.genRand.Next(23, 32 /*0x20*/);
    for (int index5 = i - num11; index5 < i + num11; ++index5)
    {
      for (int index6 = j - num11; index6 < j + num11; ++index6)
      {
        if (index6 > j + WorldGen.genRand.Next(-3, 4) - 3 && Main.tile[index5, index6].active() && Main.rand.Next(10) == 0)
        {
          double num12 = (double) Math.Abs(i - index5);
          double num13 = (double) Math.Abs(j - index6);
          if (Math.Sqrt(num12 * num12 + num13 * num13) < (double) num11 * 0.8)
          {
            if (TileID.Sets.GetsDestroyedForMeteors[(int) Main.tile[index5, index6].type])
              WorldGen.KillTile(index5, index6);
            WorldGen.paintTile(index5, index6, (byte) 0, Main.netMode == 2, false);
            WorldGen.paintCoatTile(index5, index6, (byte) 0, Main.netMode == 2, false);
            Main.tile[index5, index6].ClearSlope();
            Main.tile[index5, index6].type = (ushort) 37;
            WorldGen.SquareTileFrame(index5, index6);
          }
        }
      }
    }
    int num14 = WorldGen.genRand.Next(30, 38);
    for (int index7 = i - num14; index7 < i + num14; ++index7)
    {
      for (int index8 = j - num14; index8 < j + num14; ++index8)
      {
        if (index8 > j + WorldGen.genRand.Next(-2, 3) && Main.tile[index7, index8].active() && Main.rand.Next(20) == 0)
        {
          double num15 = (double) Math.Abs(i - index7);
          double num16 = (double) Math.Abs(j - index8);
          if (Math.Sqrt(num15 * num15 + num16 * num16) < (double) num14 * 0.85)
          {
            if (TileID.Sets.GetsDestroyedForMeteors[(int) Main.tile[index7, index8].type])
              WorldGen.KillTile(index7, index8);
            WorldGen.paintTile(index7, index8, (byte) 0, Main.netMode == 2, false);
            WorldGen.paintCoatTile(index7, index8, (byte) 0, Main.netMode == 2, false);
            Main.tile[index7, index8].ClearSlope();
            Main.tile[index7, index8].type = (ushort) 37;
            WorldGen.SquareTileFrame(index7, index8);
          }
        }
      }
    }
    WorldGen.stopDrops = false;
    if (Main.netMode == 0)
      Main.NewText(Lang.gen[59].Value, (byte) 50, B: (byte) 130);
    else if (Main.netMode == 2)
      ChatHelper.BroadcastChatMessage(NetworkText.FromKey(Lang.gen[59].Key), new Color(50, (int) byte.MaxValue, 130));
    if (Main.netMode != 1)
      NetMessage.SendTileSquare(-1, i, j, centeredSquareSize);
    return true;
  }

