  public static int GetWorldSize()
  {
    if (Main.maxTilesX <= 4200)
      return 0;
    return Main.maxTilesX <= 6400 ? 1 : 2;
  }

  public static void SetWorldSize(int size)
  {
    if (size != 0)
    {
      if (size == 1)
      {
        Main.maxTilesX = 6400;
        Main.maxTilesY = 1800;
      }
      else
      {
        Main.maxTilesX = 8400;
        Main.maxTilesY = 2400;
      }
    }
    else
    {
      Main.maxTilesX = 4200;
      Main.maxTilesY = 1200;
    }
  }

  public static void worldGenCallback(
    GenerationProgress customProgressObject,
    WorldGenerator.Controller customGenController,
    WorldGen.WorldGenerationFinishCallback afterGeneration)
  {
    SoundEngine.PlaySound(10);
    bool world = WorldGen.GenerateWorld(customProgressObject, customGenController);
    if (world)
      WorldFile.SaveWorld(Main.ActiveWorldFileData.IsCloudSave, true);
    if (Main.menuMode == 10 || Main.menuMode == 888)
      Main.menuMode = 6;
    SoundEngine.PlaySound(10);
    if (afterGeneration == null)
      return;
    afterGeneration(world);
  }

  public static Task CreateNewWorld(
    GenerationProgress progress = null,
    WorldGenerator.Controller controller = null,
    WorldGen.WorldGenerationFinishCallback afterGeneration = null)
  {
    UIWorldSelect.NewlyGeneratedWorld = Main.ActiveWorldFileData;
    WorldGen.generatingWorld = true;
    Main.rand = new UnifiedRandom(Main.ActiveWorldFileData.Seed);
    WorldGen.isGeneratingOrLoadingWorld = true;
    Main.menuMode = 888;
    try
    {
      Main.MenuUI.SetState((UIState) new UIWorldLoad());
    }
    catch
    {
    }
    return Task.Factory.StartNew((Action) (() => WorldGen.worldGenCallback(progress, controller, afterGeneration)));
  }

