  private static void SaveAndQuitCallBack(object threadContext)
  {
    Tuple<int, Action> tuple = (Tuple<int, Action>) threadContext;
    int num = tuple.Item1;
    Action action = tuple.Item2;
    Main.ActivePlayerFileData.StopPlayTimer();
    Player.SavePlayer(Main.ActivePlayerFileData);
    Player.ClearPlayerTempInfo();
    Rain.ClearRain();
    if (num == 0)
    {
      WorldFile.ReuseTempsForNextSave();
      WorldFile.SaveWorld();
      SoundEngine.PlaySound(10);
    }
    else
    {
      Netplay.Disconnect = true;
      Main.netMode = 0;
    }
    Main.fastForwardTimeToDawn = false;
    Main.fastForwardTimeToDusk = false;
    Main.UpdateTimeRate();
    Main.menuMode = 0;
    if (action == null)
      return;
    Main.QueueMainThreadAction(action);
  }

