        return 68;
    }
  }

  public static void randMoss(bool justNeon = false)
  {
    WorldGen.neonMossType = WorldGen.genRand.NextFromList<ushort>((ushort) 539, (ushort) 536, (ushort) 534, (ushort) 625);
