  public static void PrepForRegen()
  {
    using (BinaryReader reader = new BinaryReader((Stream) File.OpenRead(Main.ActiveWorldFileData.Path)))
    {
      WorldFile.LoadFileFormatHeader(reader, out bool[] _, out int[] _);
      WorldFile.LoadHeader(reader);
