  public static bool GenerateWorld(
    GenerationProgress customProgressObject = null,
    WorldGenerator.Controller customController = null)
  {
    WorldGen.generatingWorld = true;
    WorldGen.isGeneratingOrLoadingWorld = true;
    WorldGen.generatingWorldOnThisThread = true;
    bool world = false;
    try
    {
      Console.WriteLine("Creating world - Seed: {0}, Width: {1}, Height: {2}, Evil: {3}, Difficulty: {4}", (object) Main.ActiveWorldFileData.SeedText, (object) Main.maxTilesX, (object) Main.maxTilesY, (object) WorldGen.WorldGenParam_Evil, (object) Main.GameMode);
      GenVars.configuration = WorldGenConfiguration.FromEmbeddedPath("Terraria.GameContent.WorldBuilding.Configuration.json");
      WorldGen.Hooks.ProcessWorldGenConfig(ref GenVars.configuration);
      WorldGen._generator = new WorldGenerator(Main.ActiveWorldFileData.Seed, GenVars.configuration, customProgressObject, customController);
      WorldGen.clearWorld();
      WorldGen.Reset();
      WorldGen.AddPasses();
      WorldGen.DisablePassesForSpecialSeeds(WorldGen._generator._passes);
      world = WorldGen._generator.GenerateWorld();
      WorldGen.Finish();
    }
    finally
    {
      WorldGen.RestoreTemporaryStateChanges();
      WorldGen.generatingWorld = false;
      WorldGen.isGeneratingOrLoadingWorld = false;
      WorldGen.generatingWorldOnThisThread = false;
      WorldGen.drunkWorldGen = false;
      WorldGen.notTheBees = false;
      WorldGen.noTrapsWorldGen = false;
      WorldGen.getGoodWorldGen = false;
      WorldGen.tenthAnniversaryWorldGen = false;
      WorldGen.dontStarveWorldGen = false;
      WorldGen.remixWorldGen = false;
      WorldGen.everythingWorldGen = false;
      WorldGen.skyblockWorldGen = false;
    }
    return world;
  }

