  private static int GetRightMostDungeonTile()
  {
    if (GenVars.dungeonGenVars[0] == null)
      return 300;
    DungeonBounds potentialDungeonBounds = GenVars.dungeonGenVars[0].outerPotentialDungeonBounds;
    int rightMostDungeonTile = potentialDungeonBounds.Left;
    for (int left = potentialDungeonBounds.Left; left < potentialDungeonBounds.Right; ++left)
    {
      for (int top = potentialDungeonBounds.Top; top < potentialDungeonBounds.Bottom; ++top)
      {
        Tile tile = Main.tile[left, top];
        if (tile.active() && DungeonUtils.IsConsideredDungeonTile((int) tile.type) || DungeonUtils.IsConsideredDungeonWall((int) tile.wall))
        {
          rightMostDungeonTile = left;
          break;
        }
      }
    }
    return rightMostDungeonTile;
  }

  private static int GetLeftMostDungeonTile()
  {
    if (GenVars.dungeonGenVars[0] == null)
      return Main.maxTilesX - 300;
    DungeonBounds potentialDungeonBounds = GenVars.dungeonGenVars[0].outerPotentialDungeonBounds;
    int leftMostDungeonTile = potentialDungeonBounds.Right;
    for (int index = leftMostDungeonTile; index > potentialDungeonBounds.Left; --index)
    {
      for (int top = potentialDungeonBounds.Top; top < potentialDungeonBounds.Bottom; ++top)
      {
        Tile tile = Main.tile[index, top];
        if (tile.active() && DungeonUtils.IsConsideredDungeonTile((int) tile.type) || DungeonUtils.IsConsideredDungeonWall((int) tile.wall))
        {
          leftMostDungeonTile = index;
          break;
        }
      }
    }
    return leftMostDungeonTile;
  }

