  public static byte GetRainbowPaintIDForPosition(int x, int y, bool wiggly = false)
  {
    int num1 = x;
    int num2 = y;
    if (wiggly)
    {
      num1 += (int) (Math.Sin((double) (y % 50) / 50.0 * 6.2831854820251465) * 10.0) - 5;
      num2 = 0;
    }
    return (byte) (13 + (num1 % 44 + num2 % 44) % 11);
  }

