  public static bool IsItATrap(Tile tile)
  {
    if (!tile.active())
      return false;
    if (tile.actuator())
      return true;
    return TileID.Sets.Wiring.IsAMechanism[(int) tile.type] && !TileID.Sets.Wiring.IgnoreWhenValidatingTraps[(int) tile.type];
  }

  public static bool IsItATrigger(Tile tile)
