          Dust.NewDustDirect(vector2 + new Vector2(-16f, (float) (index1 * 16 /*0x10*/)) + Utils.RandomVector2(Main.rand, -30f, 30f), 4, 4, 31 /*0x1F*/, SpeedY: -3f, Alpha: 100).velocity = Main.rand.NextVector2Circular(2f, 2f) + new Vector2(0.0f, -0.6f);
