        for (int index3 = 0; index3 < num; ++index3)
        {
          Dust dust = Dust.NewDustDirect(vector2 + new Vector2(-16f, (float) (index1 * 16 /*0x10*/)) + Utils.RandomVector2(Main.rand, -30f, 30f), 4, 4, 6, SpeedY: -4f, Scale: (float) (1.0 + 0.699999988079071 * (double) Main.rand.NextFloat()));
