      return false;
    Tile tile = Main.tile[x, y];
    if (tile == null || !tile.active() || tile.type == (ushort) 323 || !TileID.Sets.IsATreeTrunk[(int) tile.type])
      return false;
    if (tile.frameX == (short) 44 && (tile.frameY == (short) 198 || tile.frameY == (short) 220 || tile.frameY == (short) 242) || tile.frameX == (short) 66 && (tile.frameY == (short) 0 || tile.frameY == (short) 22 || tile.frameY == (short) 44))
