  public static void AddTrees(bool undergroundOnly = false)
  {
    double num1 = 0.1 + WorldGen.genRand.NextDouble() * 0.35;
    double num2 = 0.1 + WorldGen.genRand.NextDouble() * 0.35;
    int num3 = 20;
    int worldSurface1 = (int) Main.worldSurface;
    if (!undergroundOnly)
    {
      for (int checkedX = 1; checkedX < Main.maxTilesX - 1; ++checkedX)
      {
        for (int checkedY = num3; checkedY < worldSurface1; ++checkedY)
        {
          if (checkedX < 380)
          {
            if (WorldGen.genRand.NextDouble() < num1 && Main.tile[checkedX, checkedY].liquid == (byte) 0)
              WorldGen.TryGrowingTreeByType(323, checkedX, checkedY);
          }
          else if (checkedX > Main.maxTilesX - 380 && WorldGen.genRand.NextDouble() < num2 && Main.tile[checkedX, checkedY].liquid == (byte) 0)
            WorldGen.TryGrowingTreeByType(323, checkedX, checkedY);
          int maxValue = 20;
          if (WorldGen.drunkWorldGen)
            maxValue /= 3;
          if (WorldGen.remixWorldGen)
            maxValue /= 2;
          if (Main.tile[checkedX, checkedY].active() && Main.tile[checkedX, checkedY].type == (ushort) 2 && (Main.tenthAnniversaryWorld || WorldGen.genRand.Next(maxValue) == 0))
          {
            if (WorldGen.genRand.Next(2) == 0)
              WorldGen.TryGrowingTreeByType(616, checkedX, checkedY);
            else
              WorldGen.TryGrowingTreeByType(596, checkedX, checkedY);
          }
          else
            WorldGen.TryGrowingTreeByType(5, checkedX, checkedY);
        }
        if (WorldGen.genRand.Next(3) == 0)
          ++checkedX;
        if (WorldGen.genRand.Next(4) == 0)
          ++checkedX;
      }
    }
    if (!WorldGen.remixWorldGen)
      return;
    int worldSurface2 = (int) Main.worldSurface;
    int num4 = Main.maxTilesY - 300;
    for (int checkedX = 1; checkedX < Main.maxTilesX - 1; ++checkedX)
    {
      for (int checkedY = worldSurface2; checkedY < num4; ++checkedY)
      {
        int maxValue = 7;
        if (Main.tile[checkedX, checkedY].active() && Main.tile[checkedX, checkedY].type == (ushort) 2 && (Main.tenthAnniversaryWorld || WorldGen.genRand.Next(maxValue) == 0))
        {
          if (WorldGen.genRand.Next(2) == 0)
            WorldGen.TryGrowingTreeByType(616, checkedX, checkedY);
          else
            WorldGen.TryGrowingTreeByType(596, checkedX, checkedY);
        }
        else
          WorldGen.TryGrowingTreeByType(5, checkedX, checkedY);
      }
    }
  }

  public static bool EmptyTileCheck(int startX, int endX, int startY, int endY, int ignoreID = -1)
  {
    if (startX < 0 || endX >= Main.maxTilesX || startY < 0 || endY >= Main.maxTilesY)
      return false;
    bool flag = false;
    if (ignoreID != -1 && TileID.Sets.CommonSapling[ignoreID])
      flag = true;
    for (int index1 = startX; index1 < endX + 1; ++index1)
    {
      for (int index2 = startY; index2 < endY + 1; ++index2)
      {
        if (Main.tile[index1, index2].active())
        {
          switch (ignoreID)
          {
            case -1:
              return false;
            case 11:
              if (Main.tile[index1, index2].type != (ushort) 11)
                return false;
              continue;
            case 71:
              if (Main.tile[index1, index2].type != (ushort) 71)
                return false;
              continue;
            default:
              if (flag && !TileID.Sets.CommonSapling[(int) Main.tile[index1, index2].type])
              {
                switch (Main.tile[index1, index2].type)
                {
                  case 3:
                  case 24:
                  case 32 /*0x20*/:
                  case 61:
                  case 62:
                  case 69:
                  case 71:
                  case 73:
                  case 74:
                  case 82:
                  case 83:
                  case 84:
                  case 110:
                  case 113:
                  case 184:
                  case 201:
                  case 233:
                  case 352:
                  case 485:
                  case 529:
                  case 530:
                  case 637:
                  case 655:
                    continue;
                  default:
                    return false;
                }
              }
              else
                continue;
          }
        }
      }
    }
    return true;
  }

  public static void TryProtectingSpawnedItems()
  {
    for (int index = 0; index < 400; ++index)
    {
      WorldItem worldItem = Main.item[index];
      if (WorldGen.EligibleForSpawnProtection(worldItem))
        worldItem.timeSinceItemSpawned -= 18000;
    }
  }

  private static bool EligibleForSpawnProtection(WorldItem item)
  {
    return item.active && ItemID.Sets.OverflowProtectionTimeOffset[item.type] == 0;
  }

  public static void UndoSpawnedItemProtection()
  {
    for (int index = 0; index < 400; ++index)
    {
      WorldItem worldItem = Main.item[index];
      if (WorldGen.EligibleForSpawnProtection(worldItem) && worldItem.timeSinceItemSpawned < 0)
        worldItem.timeSinceItemSpawned += 18000;
    }
  }

  private static void initializeHardMode()
  {
    if (Main.rand == null)
      Main.rand = new UnifiedRandom((int) DateTime.Now.Ticks);
    bool flag1 = true;
    if (Main.dualDungeonsSeed)
      flag1 = false;
    double num1 = (double) WorldGen.genRand.Next(300, 400) * 0.001;
    double num2 = (double) WorldGen.genRand.Next(200, 300) * 0.001;
    int i1 = (int) ((double) Main.maxTilesX * num1);
    int i2 = (int) ((double) Main.maxTilesX * (1.0 - num1));
    int num3 = 1;
    if (WorldGen.genRand.Next(2) == 0)
    {
      i2 = (int) ((double) Main.maxTilesX * num1);
      i1 = (int) ((double) Main.maxTilesX * (1.0 - num1));
      num3 = -1;
    }
    int num4 = 1;
    if (Main.dungeonX < Main.maxTilesX / 2)
      num4 = -1;
    if (num4 < 0)
    {
      if (i2 < i1)
        i2 = (int) ((double) Main.maxTilesX * num2);
      else
        i1 = (int) ((double) Main.maxTilesX * num2);
    }
    else if (i2 > i1)
      i2 = (int) ((double) Main.maxTilesX * (1.0 - num2));
    else
      i1 = (int) ((double) Main.maxTilesX * (1.0 - num2));
    if (flag1)
    {
      if (Main.remixWorld)
      {
        int num5 = Main.maxTilesX / 7;
        int num6 = Main.maxTilesX / 14;
        if (Main.dungeonX < Main.maxTilesX / 2)
        {
          for (int i2_1 = Main.maxTilesX - num5 - num6; i2_1 < Main.maxTilesX; ++i2_1)
          {
            for (int j2 = (int) Main.worldSurface + WorldGen.genRand.Next(-1, 2); j2 < Main.maxTilesY - 10; ++j2)
            {
              if (i2_1 > Main.maxTilesX - num5)
                WorldGen.Convert(i2_1, j2, 2);
              else if (TileID.Sets.Crimson[(int) Main.tile[i2_1, j2].type] || TileID.Sets.Corrupt[(int) Main.tile[i2_1, j2].type])
                WorldGen.Convert(i2_1, j2, 2);
            }
          }
        }
        else
        {
          for (int i2_2 = 0; i2_2 < num5 + num6; ++i2_2)
          {
            for (int j2 = (int) Main.worldSurface + WorldGen.genRand.Next(-1, 2); j2 < Main.maxTilesY - 10; ++j2)
            {
              if (i2_2 < num5)
                WorldGen.Convert(i2_2, j2, 2);
              else if (TileID.Sets.Crimson[(int) Main.tile[i2_2, j2].type] || TileID.Sets.Corrupt[(int) Main.tile[i2_2, j2].type])
                WorldGen.Convert(i2_2, j2, 2);
            }
          }
        }
      }
      else
      {
        WorldGen.GERunner(i1, 0, (double) (3 * num3), 5.0);
        WorldGen.GERunner(i2, 0, (double) (3 * -num3), 5.0, false);
      }
    }
    int num7 = (int) (25.0 * ((double) Main.maxTilesX / 4200.0));
    ShapeData data = new ShapeData();
    int num8 = 0;
    while (num7 > 0)
    {
      if (++num8 % 15000 == 0)
        --num7;
      Point point = Main.worldSurface <= 100.0 ? WorldGen.RandomWorldPoint(20, 1, 190, 1) : WorldGen.RandomWorldPoint((int) Main.worldSurface - 100, 1, 190, 1);
      Tile tile1 = Main.tile[point.X, point.Y];
      Tile tile2 = Main.tile[point.X, point.Y - 1];
      ushort type = 0;
      if (TileID.Sets.Crimson[(int) tile1.type])
        type = (ushort) (192 /*0xC0*/ + WorldGen.genRand.Next(4));
      else if (TileID.Sets.Corrupt[(int) tile1.type])
        type = (ushort) (188 + WorldGen.genRand.Next(4));
      else if (TileID.Sets.Hallow[(int) tile1.type])
        type = (ushort) (200 + WorldGen.genRand.Next(4));
      if (tile1.active() && type != (ushort) 0 && !tile2.active())
      {
        bool flag2 = WorldUtils.Gen(new Point(point.X, point.Y - 1), (GenShape) new ShapeFloodFill(1000), Terraria.WorldBuilding.Actions.Chain((GenAction) new Modifiers.IsNotSolid(), (GenAction) new Modifiers.OnlyWalls(new ushort[31 /*0x1F*/]
        {
          (ushort) 0,
          (ushort) 54,
          (ushort) 55,
          (ushort) 56,
          (ushort) 57,
          (ushort) 58,
          (ushort) 59,
          (ushort) 61,
          (ushort) 185,
          (ushort) 212,
          (ushort) 213,
          (ushort) 214,
          (ushort) 215,
          (ushort) 2,
          (ushort) 196,
          (ushort) 197,
          (ushort) 198,
          (ushort) 199,
          (ushort) 15,
          (ushort) 40,
          (ushort) 71,
          (ushort) 64 /*0x40*/,
          (ushort) 204,
          (ushort) 205,
          (ushort) 206,
          (ushort) 207,
          (ushort) 208 /*0xD0*/,
          (ushort) 209,
          (ushort) 210,
          (ushort) 211,
          (ushort) 71
        }), new Terraria.WorldBuilding.Actions.Blank().Output(data)));
        if (data.Count > 50 & flag2)
        {
          WorldUtils.Gen(new Point(point.X, point.Y), (GenShape) new ModShapes.OuterOutline(data, useInterior: true), (GenAction) new Terraria.WorldBuilding.Actions.PlaceWall(type));
          --num7;
        }
        data.Clear();
      }
    }
  }

  public static void StartHardmode(bool force = false)
  {
    if (Main.netMode == 1 || Main.hardMode && !force)
      return;
    Main.hardMode = true;
    WorldGen.TryProtectingSpawnedItems();
    WorldGen.TransformWorldOnBackgroundThread(new Action(WorldGen.initializeHardMode), (Action) (() =>
    {
      switch (Main.netMode)
      {
        case 0:
          Main.NewText(Lang.misc[15].Value, (byte) 50, B: (byte) 130);
          break;
        case 2:
          ChatHelper.BroadcastChatMessage(NetworkText.FromKey(Lang.misc[15].Key), new Color(50, (int) byte.MaxValue, 130));
          break;
      }
      AchievementsHelper.NotifyProgressionEvent(9);
      if (Main.netMode == 2)
        Netplay.ResetSections();
      WorldGen.UndoSpawnedItemProtection();
    }));
  }

  public static void TransformWorldOnBackgroundThread(Action transform, Action mainThreadFollowup)
  {
    Interlocked.Increment(ref WorldGen._transformingWorld);
    Task.Factory.StartNew((Action) (() =>
    {
      try
      {
        lock (WorldFile.IOLock)
          transform();
      }
      finally
      {
        Interlocked.Decrement(ref WorldGen._transformingWorld);
        if (mainThreadFollowup != null)
          Main.QueueMainThreadAction(mainThreadFollowup);
      }
    }));
  }

  public static void ClearUnbreakableWallsWithPaintUpTo(int tierColor)
  {
    if (Main.netMode == 1)
      return;
    WorldGen.TransformWorldOnBackgroundThread((Action) (() =>
    {
      for (int index1 = 0; index1 < Main.maxTilesX; ++index1)
      {
        for (int index2 = 0; index2 < Main.maxTilesY; ++index2)
        {
          Tile tile = Main.tile[index1, index2];
          if (tile.wall == (ushort) 350 && ((int) tile.wallColor() & 15) <= tierColor)
          {
            tile.wall = TileID.Sets.MatchingUnsafeWall[(int) tile.type];
            tile.wallColor((byte) 0);
          }
        }
      }
    }), (Action) (() =>
    {
      if (Main.netMode != 2)
        return;
      Netplay.ResetSections();
    }));
  }

