  public static bool CloseDoor(int i, int j, bool forced = false)
  {
    int num1 = 0;
    int num2 = i;
    if (Main.tile[i, j] == null)
      Main.tile[i, j] = new Tile();
    int frameX = (int) Main.tile[i, j].frameX;
    Tile tile1 = Main.tile[i, j];
    if (tile1.type != (ushort) 11)
      return false;
    int frameY = (int) tile1.frameY;
    int num3 = 0;
    int num4 = 0;
    while (frameY >= 54)
    {
      frameY -= 54;
      ++num3;
    }
    if (frameX >= 72)
    {
      int num5 = num3 + 36 * (frameX / 72);
      num4 += 54 * (frameX / 72);
    }
    int num6 = j - frameY / 18;
    switch (frameX % 72)
    {
      case 0:
        num2 = i;
        num1 = 1;
        break;
      case 18:
        num2 = i - 1;
        num1 = 1;
        break;
      case 36:
        num2 = i + 1;
        num1 = -1;
        break;
      case 54:
        num2 = i;
        num1 = -1;
        break;
    }
    int topLeftX = num2;
    if (num1 == -1)
      topLeftX = num2 - 1;
    if (!forced)
    {
      for (int j1 = num6; j1 < num6 + 3; ++j1)
      {
        if (!Collision.EmptyTile(num2, j1, true))
          return false;
      }
    }
    if (!WorldGen.ValidateTileSquareIsActiveAndOfType(topLeftX, num6, 2, 3, 11))
      return false;
    for (int index1 = topLeftX; index1 < topLeftX + 2; ++index1)
    {
      for (int index2 = num6; index2 < num6 + 3; ++index2)
      {
        if (Main.tile[index1, index2] == null)
          Main.tile[index1, index2] = new Tile();
        Tile tile2 = Main.tile[index1, index2];
        if (tile2.active() && tile2.type == (ushort) 11)
        {
          if (index1 == num2)
          {
            tile2.type = (ushort) 10;
            tile2.frameX = (short) (WorldGen.genRand.Next(3) * 18 + num4);
          }
          else
            tile2.active(false);
        }
      }
    }
    if (Main.netMode != 1 && Wiring.running)
    {
      Wiring.SkipWire(num2, num6);
      Wiring.SkipWire(num2, num6 + 1);
      Wiring.SkipWire(num2, num6 + 2);
    }
    for (int i1 = num2 - 1; i1 <= num2 + 1; ++i1)
    {
      for (int j2 = num6 - 1; j2 <= num6 + 2; ++j2)
        WorldGen.TileFrame(i1, j2);
    }
    SoundEngine.PlaySound(9, i * 16 /*0x10*/, j * 16 /*0x10*/);
    return true;
  }

