  public static void Check1xX(int x, int j, short type)
  {
    if (WorldGen.destroyObject)
      return;
    int frameX = (int) Main.tile[x, j].frameX;
    int num1 = 3;
    if (type == (short) 92)
      num1 = 6;
    int frameY = (int) Main.tile[x, j].frameY;
    int style = 0;
    while (frameY >= 18 * num1)
    {
      frameY -= 18 * num1;
      ++style;
    }
    int num2 = (int) Main.tile[x, j].frameX / 18;
    int num3 = j - frameY / 18;
    bool flag = false;
    for (int index = 0; index < num1; ++index)
    {
      if (Main.tile[x, num3 + index] == null)
        Main.tile[x, num3 + index] = new Tile();
      if (!Main.tile[x, num3 + index].active())
        flag = true;
      else if ((int) Main.tile[x, num3 + index].type != (int) type)
        flag = true;
      else if ((int) Main.tile[x, num3 + index].frameY != index * 18 + style * num1 * 18)
        flag = true;
      else if ((int) Main.tile[x, num3 + index].frameX != frameX)
        flag = true;
    }
    if (Main.tile[x, num3 + num1] == null)
      Main.tile[x, num3 + num1] = new Tile();
    if (!WorldGen.SolidTileAllowBottomSlope(x, num3 + num1))
      flag = true;
    if (!flag)
      return;
    WorldGen.destroyObject = true;
    for (int index = 0; index < num1; ++index)
    {
      if ((int) Main.tile[x, num3 + index].type == (int) type)
        WorldGen.KillTile(x, num3 + index);
    }
    if (type == (short) 92)
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, j), x * 16 /*0x10*/, j * 16 /*0x10*/, 32 /*0x20*/, 32 /*0x20*/, 341);
    if (type == (short) 453)
    {
      int Type = num2 >= 2 ? (num2 >= 4 ? 3743 : 3745) : 3744;
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, j), x * 16 /*0x10*/, j * 16 /*0x10*/, 16 /*0x10*/, 32 /*0x20*/, Type);
    }
    if (type == (short) 93)
    {
      int itemDropLamps = WorldGen.GetItemDrop_Lamps(style);
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, j), x * 16 /*0x10*/, j * 16 /*0x10*/, 32 /*0x20*/, 32 /*0x20*/, itemDropLamps);
    }
    WorldGen.destroyObject = false;
  }

  public static bool ValidateTileSquareIsActiveAndOfType(
    int topLeftX,
    int topLeftY,
    int width,
    int height,
    int type)
  {
    bool flag = false;
    for (int index1 = 0; index1 < width; ++index1)
    {
      for (int index2 = 0; index2 < height; ++index2)
      {
        int x = topLeftX + index1;
        int y = topLeftY + index2;
        if (!WorldGen.InWorld(x, y))
          return false;
        Tile tile = Main.tile[x, y];
        if (tile != null && (!tile.active() || (int) tile.type != type))
        {
          flag = true;
          break;
        }
      }
      if (flag)
        break;
    }
    if (!flag)
      return true;
    for (int index3 = 0; index3 < width; ++index3)
    {
      for (int index4 = 0; index4 < height; ++index4)
      {
        int index5 = topLeftX + index3;
        int index6 = topLeftY + index4;
        Tile tile = Main.tile[index5, index6];
        if (tile != null && tile.active() && (int) tile.type == type)
        {
          WorldGen.KillTile(index5, index6);
          if (Main.netMode != 0)
            NetMessage.SendData(17, number2: (float) index5, number3: (float) index6);
        }
      }
    }
    return false;
  }

