  public static bool UpdateStalagtiteStyle(int x, int j)
  {
    if (Main.netMode == 1 || Main.tile[x, j] == null)
      return true;
    int style;
    bool fail1;
    WorldGen.GetStalagtiteStyle(x, j, out style, out fail1);
    if (fail1)
      return false;
    bool fail2;
    int desiredStyle;
    int height;
    int y;
    WorldGen.GetDesiredStalagtiteStyle(x, j, out fail2, out desiredStyle, out height, out y);
    if (fail2)
      return false;
    if (style != desiredStyle)
    {
      int num = WorldGen.genRand.Next(3) * 18;
      switch (desiredStyle)
      {
        case 0:
          num += 54;
          break;
        case 1:
          num += 216;
          break;
        case 2:
          num += 270;
          break;
        case 3:
          num += 324;
          break;
        case 4:
          num += 378;
          break;
        case 5:
          num += 432;
          break;
        case 6:
          num += 486;
          break;
        case 7:
          num = num;
          break;
        case 8:
          num += 540;
          break;
        case 9:
          num += 594;
          break;
        case 10:
          num += 648;
          break;
        case 11:
          num += 108;
          break;
        case 12:
          num += 162;
          break;
      }
      for (int index = y; index < y + height; ++index)
        Main.tile[x, index].frameX = (short) num;
      if (Main.netMode == 2)
        NetMessage.SendTileSquare(-1, x, y, 1, 2);
    }
    return true;
  }

  private static void GetDesiredStalagtiteStyle(
    int x,
    int j,
    out bool fail,
    out int desiredStyle,
    out int height,
    out int y)
  {
    fail = false;
    desiredStyle = 0;
    height = 1;
    y = j;
    Tile tile1 = Main.tile[x, y];
    int num;
    int type;
    if (tile1.frameY == (short) 72)
    {
      Tile tile2 = Main.tile[x, y - 1];
      num = 0;
      type = (int) tile2.type;
    }
    else if (tile1.frameY == (short) 90)
    {
      Tile tile3 = Main.tile[x, y + 1];
      num = 1;
      type = (int) tile3.type;
    }
    else if (tile1.frameY >= (short) 36)
    {
      if (tile1.frameY == (short) 54)
        --y;
      height = 2;
      Tile tile4 = Main.tile[x, y + 2];
      num = 4;
      type = (int) tile4.type;
    }
    else
    {
      if (tile1.frameY == (short) 18)
        --y;
      height = 2;
      Tile tile5 = Main.tile[x, y - 1];
      num = 3;
      type = (int) tile5.type;
    }
    if (type == 1 || Main.tileMoss[type])
    {
      desiredStyle = 0;
      if (num != 3 || tile1.wall != (ushort) 62)
        return;
      desiredStyle = 11;
    }
    else
    {
      switch (type)
      {
        case 25:
        case 398:
        case 400:
          desiredStyle = 2;
          break;
        case 117:
        case 402:
        case 403:
          desiredStyle = 1;
          break;
        case 147:
        case 161:
          desiredStyle = 7;
          break;
        case 163:
          desiredStyle = 9;
          break;
        case 164:
          desiredStyle = 8;
          break;
        case 200:
          desiredStyle = 10;
          break;
        case 203:
        case 399:
        case 401:
          desiredStyle = 3;
          break;
        case 367:
          desiredStyle = 6;
          break;
        case 368:
          desiredStyle = 5;
          break;
        case 396:
        case 397:
          desiredStyle = 4;
          break;
        default:
          if ((num == 0 || num == 1) && type == 225)
          {
            desiredStyle = 12;
            break;
          }
          fail = true;
          break;
      }
    }
  }

