  public static void CheckStalactiteEcho(int x, int j)
  {
    Tile tile1 = Main.tile[x, j];
    ushort type = tile1.type;
    int num1 = type == (ushort) 694 ? 2 : 1;
    int num2 = (int) tile1.frameY < num1 * 18 ? 1 : 0;
    int style = (int) tile1.frameX / 18;
    int num3 = j - (int) tile1.frameY % (num1 * 18) / 18;
    int num4 = num2 != 0 ? 0 : 18 * num1;
    int j1 = num2 != 0 ? num3 - 1 : num3 + num1;
    bool flag = num2 != 0 ? !WorldGen.SolidTileAllowTopSlope(x, j1) : !WorldGen.SolidTileAllowBottomSlope(x, j1);
    if (!flag)
    {
      int index = num3;
      int num5 = 0;
      while (index < num3 + num1)
      {
        Tile tile2 = Main.tile[x, index];
        if ((int) tile2.type != (int) type || (int) tile2.frameX != (int) tile1.frameX || (int) tile2.frameY != num4 + num5)
        {
          flag = true;
          break;
        }
        ++index;
        num5 += 18;
      }
    }
    if (!flag)
      return;
    WorldGen.destroyObject = true;
    for (int j2 = num3; j2 < num3 + num1; ++j2)
    {
      if ((int) Main.tile[x, j2].type == (int) type)
        WorldGen.KillTile(x, j2);
    }
    WorldGen.destroyObject = false;
    int stalactiteEchoDrop = WorldGen.GetStalactiteEchoDrop(x, j, style);
    if (stalactiteEchoDrop == 0)
      return;
    Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, j), x * 16 /*0x10*/, j * 16 /*0x10*/, 16 /*0x10*/, 32 /*0x20*/, stalactiteEchoDrop);
  }

