  public static void Check1x2(int x, int j, ushort type)
  {
    if (WorldGen.destroyObject)
      return;
    int index = j;
    bool flag = true;
    if (Main.tile[x, index] == null)
      Main.tile[x, index] = new Tile();
    if (Main.tile[x, index + 1] == null)
      Main.tile[x, index + 1] = new Tile();
    short frameY = Main.tile[x, index].frameY;
    int style = 0;
    while (frameY >= (short) 40)
    {
      frameY -= (short) 40;
      ++style;
    }
    if (frameY == (short) 18)
      --index;
    if (Main.tile[x, index] == null)
      Main.tile[x, index] = new Tile();
    int num1 = (int) Main.tile[x, index].frameX / 18;
    if (Main.tile[x, index].frameX == (short) -1)
      num1 = (int) Main.tile[x, index + 1].frameX / 18;
    if ((int) Main.tile[x, index].frameY == 40 * style && (int) Main.tile[x, index + 1].frameY == 40 * style + 18 && (int) Main.tile[x, index].type == (int) type && (int) Main.tile[x, index + 1].type == (int) type)
      flag = false;
    if (Main.tile[x, index + 2] == null)
      Main.tile[x, index + 2] = new Tile();
    if (!WorldGen.SolidTileAllowBottomSlope(x, index + 2) && !TileID.Sets.Platforms[(int) Main.tile[x, index + 2].type])
      flag = true;
    if (Main.tile[x, index].type == (ushort) 20)
    {
      int num2 = (int) Main.tile[x, index].frameX / 54;
      ushort type1 = Main.tile[x, index + 2].type;
      int num3 = -1;
      switch (type1)
      {
        case 2:
        case 477:
          num3 = 0;
          break;
        case 23:
        case 661:
          num3 = 3;
          break;
        case 53:
          num3 = 6;
          break;
        case 60:
          num3 = 2;
          break;
        case 109:
        case 492:
          num3 = 5;
          break;
        case 112 /*0x70*/:
          num3 = 9;
          break;
        case 116:
          num3 = 7;
          break;
        case 147:
          num3 = 1;
          break;
        case 199:
        case 662:
          num3 = 4;
          break;
        case 234:
          num3 = 8;
          break;
        case 633:
          num3 = 10;
          break;
        default:
          flag = true;
          break;
      }
      if (!flag && num2 != num3)
      {
        int num4 = 54 * num3 + WorldGen.genRand.Next(3) * 18;
        Main.tile[x, index].frameX = (short) num4;
        Main.tile[x, index + 1].frameX = (short) num4;
      }
    }
    if (!flag)
      return;
    WorldGen.destroyObject = true;
    if ((int) Main.tile[x, index].type == (int) type)
      WorldGen.KillTile(x, index);
    if ((int) Main.tile[x, index + 1].type == (int) type)
      WorldGen.KillTile(x, index + 1);
    if (type == (ushort) 216)
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, index), x * 16 /*0x10*/, index * 16 /*0x10*/, 32 /*0x20*/, 32 /*0x20*/, 970 + style);
    if (type == (ushort) 338)
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, index), x * 16 /*0x10*/, index * 16 /*0x10*/, 32 /*0x20*/, 32 /*0x20*/, 2738);
    if (type == (ushort) 390)
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, index), x * 16 /*0x10*/, index * 16 /*0x10*/, 16 /*0x10*/, 32 /*0x20*/, 3253);
    if (type == (ushort) 493)
    {
      int Type = 0;
      switch (num1)
      {
        case 0:
          Type = 4083;
          break;
        case 1:
          Type = 4084;
          break;
        case 2:
          Type = 4085;
          break;
        case 3:
          Type = 4086;
          break;
        case 4:
          Type = 4087;
          break;
        case 5:
          Type = 4088;
          break;
      }
      if (Type > 0)
        Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, index), x * 16 /*0x10*/, index * 16 /*0x10*/, 32 /*0x20*/, 32 /*0x20*/, Type);
    }
    if (type == (ushort) 15)
    {
      int itemDropChair = WorldGen.GetItemDrop_Chair(style);
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, index), x * 16 /*0x10*/, index * 16 /*0x10*/, 32 /*0x20*/, 32 /*0x20*/, itemDropChair);
    }
    if (type == (ushort) 497)
    {
      int itemDropToilet = WorldGen.GetItemDrop_Toilet(style);
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, index), x * 16 /*0x10*/, index * 16 /*0x10*/, 32 /*0x20*/, 32 /*0x20*/, itemDropToilet);
