    }
    if (Main.tile[index1, index2].active())
      return;
    int num3 = 0;
    if (Main.tile[index1 + 1, index2].active() && (int) Main.tile[index1 + 1, index2].type == (int) spikeType)
      ++num3;
    if (Main.tile[index1 - 1, index2].active() && (int) Main.tile[index1 - 1, index2].type == (int) spikeType)
