  public static void CheckMB(int i, int j, int type)
  {
    if (WorldGen.destroyObject)
      return;
    bool flag = false;
    int style = 0;
    int num1;
    for (num1 = (int) Main.tile[i, j].frameY / 18; num1 >= 2; num1 -= 2)
      ++style;
    int num2 = (int) Main.tile[i, j].frameX / 18;
    int num3 = 0;
    if (num2 >= 2)
    {
      num2 -= 2;
      ++num3;
    }
    int num4 = i - num2;
    int num5 = j - num1;
    for (int index1 = num4; index1 < num4 + 2; ++index1)
    {
      for (int index2 = num5; index2 < num5 + 2; ++index2)
      {
        if (Main.tile[index1, index2] == null)
          Main.tile[index1, index2] = new Tile();
        if (!Main.tile[index1, index2].active() || (int) Main.tile[index1, index2].type != type || (int) Main.tile[index1, index2].frameX != (index1 - num4) * 18 + num3 * 36 || (int) Main.tile[index1, index2].frameY != (index2 - num5) * 18 + style * 36)
          flag = true;
      }
      if (!Main.tile[index1, num5 + 2].nactive())
        flag = true;
      else if (!Main.tileSolid[(int) Main.tile[index1, num5 + 2].type] && !Main.tileTable[(int) Main.tile[index1, num5 + 2].type])
        flag = true;
    }
    if (!flag)
      return;
    WorldGen.destroyObject = true;
    for (int i1 = num4; i1 < num4 + 2; ++i1)
    {
      for (int j1 = num5; j1 < num5 + 3; ++j1)
      {
        if ((int) Main.tile[i1, j1].type == type && Main.tile[i1, j1].active())
          WorldGen.KillTile(i1, j1);
      }
    }
    if (type == 35)
    {
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(i, j), i * 16 /*0x10*/, j * 16 /*0x10*/, 32 /*0x20*/, 32 /*0x20*/, 1813);
    }
    else
    {
      int itemDropMusicBoxes = WorldGen.GetItemDrop_MusicBoxes(style);
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(i, j), i * 16 /*0x10*/, j * 16 /*0x10*/, 32 /*0x20*/, 32 /*0x20*/, itemDropMusicBoxes);
    }
    for (int i2 = num4 - 1; i2 < num4 + 3; ++i2)
    {
      for (int j2 = num5 - 1; j2 < num5 + 3; ++j2)
        WorldGen.TileFrame(i2, j2);
    }
    WorldGen.destroyObject = false;
  }

  public static void PlaceMB(int X, int y, ushort type, int style)
  {
    int index1 = X + 1;
    if (index1 < 5 || index1 > Main.maxTilesX - 5 || y < 5 || y > Main.maxTilesY - 5)
      return;
    bool flag = true;
    for (int index2 = index1 - 1; index2 < index1 + 1; ++index2)
    {
      for (int index3 = y - 1; index3 < y + 1; ++index3)
      {
        if (Main.tile[index2, index3] == null)
          Main.tile[index2, index3] = new Tile();
        if (Main.tile[index2, index3].active())
          flag = false;
      }
      if (Main.tile[index2, y + 1] == null)
        Main.tile[index2, y + 1] = new Tile();
      if (!Main.tile[index2, y + 1].active() || Main.tile[index2, y + 1].halfBrick() || !Main.tileSolid[(int) Main.tile[index2, y + 1].type] && !Main.tileTable[(int) Main.tile[index2, y + 1].type])
