  public static bool ValidateOrAttemptReorientingAnchor(
    int x,
    int y,
    int wall,
    ref int style,
    bool switchToWallIfInvalid = false)
  {
    if (style == 0 && !WorldGen.SolidTileAllowBottomSlope(x, y + 1) && !WorldGen.ConsideredSolidTileForAnchor(x, y + 1))
      style = -1;
    if (style == 1 && !WorldGen.SolidTileAllowTopSlope(x, y - 1) && !WorldGen.ConsideredSolidTileForAnchor(x, y - 1))
      style = -1;
    if (style == 2 && !WorldGen.SolidTileAllowLeftSlope(x - 1, y) && !WorldGen.ConsideredSolidTileForAnchor(x - 1, y))
      style = -1;
    if (style == 3 && !WorldGen.SolidTileAllowRightSlope(x + 1, y) && !WorldGen.ConsideredSolidTileForAnchor(x + 1, y))
      style = -1;
    if (style == 4 && wall <= 0)
      style = -1;
    if (style == -1 && (WorldGen.SolidTileAllowBottomSlope(x, y + 1) || WorldGen.ConsideredSolidTileForAnchor(x, y + 1)))
      style = 0;
    if (style == -1 && (WorldGen.SolidTileAllowTopSlope(x, y - 1) || WorldGen.ConsideredSolidTileForAnchor(x, y - 1)))
      style = 1;
    if (style == -1 && (WorldGen.SolidTileAllowLeftSlope(x - 1, y) || WorldGen.ConsideredSolidTileForAnchor(x - 1, y)))
      style = 2;
    if (style == -1 && (WorldGen.SolidTileAllowRightSlope(x + 1, y) || WorldGen.ConsideredSolidTileForAnchor(x + 1, y)))
      style = 3;
    if (style == -1 && wall > 0)
      style = 4;
    if (switchToWallIfInvalid && style == -1)
      style = 4;
    return style > -1;
  }

  private static bool ConsideredSolidTileForAnchor(int x, int y)
  {
    if (!WorldGen.InWorld(x, y))
      return true;
    Tile t = Main.tile[x, y];
    if (t == null)
      return true;
    if (!t.active())
      return false;
    int offsetToTrunk = 0;
    return t.type >= (ushort) 0 && (t.type == (ushort) 323 || TileID.Sets.IsATreeTrunk[(int) t.type] && !WorldGen.IsTileATreeBranch(x, y, out offsetToTrunk)) && !WorldGen.IsTileALeafyTreeTop(t);
  }

