    int y,
    int newFloorType,
    int oldTreeType,
    int newTreeType)
  {
    if (!WorldGen.InWorld(x, y, 5))
      return;
    Tile tile1 = Main.tile[x, y + 1];
    if (tile1 == null || !tile1.active())
      return;
    int num1 = 100;
