        if (tile2 != null && tile2.active() && (tile2.type == (ushort) 323 || TileID.Sets.IsATreeTrunk[(int) tile2.type]) && !WorldGen.IsTileATreeBranch(x, y - 1, out offsetToTrunk1))
          ++num2;
