  private static void ConvertTreeAndGround_Branches(int x, int y, int newType)
  {
    int offsetToTrunk = 0;
    if (WorldGen.IsTileATreeBranch(x - 1, y, out offsetToTrunk) && offsetToTrunk == 1 || WorldGen.IsTileATreeRoot(x - 1, y, out offsetToTrunk) && offsetToTrunk == 1)
      Main.tile[x - 1, y].type = (ushort) newType;
    if ((!WorldGen.IsTileATreeBranch(x + 1, y, out offsetToTrunk) || offsetToTrunk != -1) && (!WorldGen.IsTileATreeRoot(x + 1, y, out offsetToTrunk) || offsetToTrunk != -1))
      return;
    Main.tile[x + 1, y].type = (ushort) newType;
  }

  public static void Convert(int i, int j, int conversionType, int size, bool tiles = true, bool walls = true)
  {
    if (!tiles && !walls)
      return;
    for (int index1 = i - size; index1 <= i + size; ++index1)
    {
      for (int index2 = j - size; index2 <= j + size; ++index2)
      {
        if (WorldGen.InWorld(index1, index2, 1) && Math.Abs(index1 - i) + Math.Abs(index2 - j) < 6)
          WorldGen.Convert(index1, index2, conversionType, tiles, walls);
      }
    }
  }

  public static void Convert(int i2, int j2, int conversionType, bool tiles = true, bool walls = true)
  {
    if (!WorldGen.InWorld(i2, j2, 1) || !tiles && !walls)
      return;
    Tile theTile = Main.tile[i2, j2];
    ushort type = theTile.type;
    ushort wall = theTile.wall;
    if (!theTile.active() && wall <= (ushort) 0)
      return;
    switch (conversionType)
    {
      case 0:
        if (walls)
        {
          if (theTile.wall == (ushort) 69 || theTile.wall == (ushort) 70 || theTile.wall == (ushort) 81)
          {
            ushort newType = 64 /*0x40*/;
            if ((double) j2 < Main.worldSurface)
              newType = WorldGen.genRand.Next(10) != 0 ? (ushort) 63 /*0x3F*/ : (ushort) 65;
            WorldGen.Convert_ActuallyConvertWall(conversionType, i2, j2, ref theTile, (int) newType);
          }
          else
