  public static void Convert_ActuallyConvertTorch(
    int conversionType,
    int x,
    int y,
    ref Tile theTile,
    int newStyle)
  {
    if (!theTile.active() || theTile.type != (ushort) 4)
      return;
    int num1 = (int) theTile.frameY / 22;
    if (conversionType == 0 && num1 == 22)
      newStyle = 21;
    if (num1 == newStyle)
      return;
    int num2 = conversionType == 1 || conversionType == 4 ? 1 : (conversionType == 2 ? 1 : 0);
    theTile.frameY = (short) (newStyle * 22);
    if (num2 != 0 && SpecialSeedFeatures.RainbowSandAndBlackSandWalls)
    {
      WorldGen.paintTile(x, y, (byte) 0, true);
      WorldGen.paintCoatTile(x, y, (byte) 0, true);
    }
    WorldGen.SquareTileFrame(x, y);
    NetMessage.SendTileSquare(-1, x, y);
  }

  private static void Convert_ActuallyConvertTile(
    int conversionType,
    int x,
    int y,
    ref Tile theTile,
    int newType)
  {
    if (!theTile.active() || (int) theTile.type == newType)
      return;
    int num = conversionType == 1 || conversionType == 4 ? 1 : (conversionType == 2 ? 1 : 0);
    WorldGen.TryConvertingOrKillingTreesAboveIfTheyWouldBecomeInvalid(x, y, newType);
    theTile.type = (ushort) newType;
    if (num != 0 && SpecialSeedFeatures.RainbowSandAndBlackSandWalls)
    {
      WorldGen.paintTile(x, y, (byte) 0, true);
      WorldGen.paintCoatTile(x, y, (byte) 0, true);
    }
    WorldGen.SquareTileFrame(x, y);
    NetMessage.SendTileSquare(-1, x, y);
  }

