  public static bool AddWireFromPointToPoint(
    int x,
    int y,
    int x2,
    int y2,
    int wireColor = 0,
    bool debugPaint = false)
  {
    if (!WorldGen.InWorld(x, y) || !WorldGen.InWorld(x2, y2))
      return false;
    while (x2 != x || y2 != y)
    {
      WorldGen.AddWire(x2, y2, wireColor);
      if (debugPaint)
      {
        WorldGen.paintWall(x2, y2, (byte) 21, paintEffects: false);
        WorldGen.paintTile(x2, y2, (byte) 21, paintEffects: false);
      }
      if (x2 > x)
        --x2;
      if (x2 < x)
        ++x2;
      WorldGen.AddWire(x2, y2, wireColor);
      if (debugPaint)
      {
        WorldGen.paintWall(x2, y2, (byte) 21, paintEffects: false);
        WorldGen.paintTile(x2, y2, (byte) 21, paintEffects: false);
      }
      if (y2 > y)
        --y2;
      if (y2 < y)
        ++y2;
      WorldGen.AddWire(x2, y2, wireColor);
      if (debugPaint)
      {
        WorldGen.paintWall(x2, y2, (byte) 21, paintEffects: false);
        WorldGen.paintTile(x2, y2, (byte) 21, paintEffects: false);
      }
    }
    return true;
  }

