    if (Main.tile[x, y].wall > (ushort) 0 || Main.tile[x, y].active() || Main.tile[x, y].liquid > (byte) 0 || !WorldGen.SolidTileAllowBottomSlope(x, y + 1) || !TileID.Sets.Conversion.Sand[(int) Main.tile[x, y + 1].type] || !WorldGen.SeaOatWaterCheck(x, y) || Main.tile[x, y + 1] == null)
      return false;
    TileColorCache cache = Main.tile[x, y + 1].BlockColorAndCoating();
    Main.tile[x, y].active(true);
    Main.tile[x, y].slope((byte) 0);
