    if (index3 >= 0 && Main.tileSolid[index3] && !Main.tileSolidTop[index3])
    {
      newFrameDirection = 2;
      return true;
    }
    if (index4 >= 0 && Main.tileSolid[index4] && !Main.tileSolidTop[index4])
    {
      newFrameDirection = 3;
      return true;
    }
    if (index2 < 0 || !Main.tileSolid[index2] || Main.tileSolidTop[index2])
      return false;
    newFrameDirection = 1;
    return true;
  }

  public static void KillWall(int i, int j, bool fail = false)
  {
    if (i < 0 || j < 0 || i >= Main.maxTilesX || j >= Main.maxTilesY)
      return;
    Tile tileCache = Main.tile[i, j];
    if (tileCache == null)
    {
      tileCache = new Tile();
      Main.tile[i, j] = tileCache;
    }
    if (tileCache.wall <= (ushort) 0)
      return;
    fail = WorldGen.KillWall_CheckFailure(fail, tileCache);
    WorldGen.KillWall_PlaySounds(i, j, tileCache);
    int num = 10;
    if (fail)
      num = 3;
    for (int index = 0; index < num; ++index)
      WorldGen.KillWall_MakeWallDust(i, j, tileCache);
    if (fail)
    {
      WorldGen.SquareWallFrame(i, j);
    }
    else
    {
      WorldGen.KillWall_DropItems(i, j, tileCache);
      tileCache.wall = (ushort) 0;
      tileCache.ClearWallPaintAndCoating();
      WorldGen.SquareWallFrame(i, j);
      if (tileCache.type < (ushort) 0 || (int) tileCache.type >= (int) TileID.Count || !TileID.Sets.FramesOnKillWall[(int) tileCache.type])
        return;
      WorldGen.TileFrame(i, j);
    }
  }

  private static bool KillWall_CheckFailure(bool fail, Tile tileCache)
  {
    if (Main.wallDungeon[(int) tileCache.wall] && !NPC.downedBoss3)
      fail = true;
    if (tileCache.wall == (ushort) 87 && !NPC.downedGolemBoss)
      fail = true;
    return fail;
  }

  private static void KillWall_PlaySounds(int i, int j, Tile tileCache)
  {
    if (tileCache.wall == (ushort) 241 || tileCache.wall >= (ushort) 88 && tileCache.wall <= (ushort) 93 || tileCache.wall == (ushort) 21 || tileCache.wall == (ushort) 186 || tileCache.wall == (ushort) 136 || tileCache.wall == (ushort) 137 || tileCache.wall == (ushort) 168 || tileCache.wall == (ushort) 169 || tileCache.wall == (ushort) 172 || tileCache.wall == (ushort) 226 || tileCache.wall == (ushort) 227 || tileCache.wall == (ushort) 242 || tileCache.wall == (ushort) 243 || tileCache.wall == (ushort) 347 || tileCache.wall == (ushort) 365)
      SoundEngine.PlaySound(13, i * 16 /*0x10*/, j * 16 /*0x10*/);
    else if (tileCache.wall >= (ushort) 63 /*0x3F*/ && tileCache.wall <= (ushort) 70 || tileCache.wall == (ushort) 264 || tileCache.wall == (ushort) 268 || tileCache.wall == (ushort) 265)
      SoundEngine.PlaySound(6, i * 16 /*0x10*/, j * 16 /*0x10*/);
    else if (tileCache.wall == (ushort) 357)
      SoundEngine.PlaySound(SoundID.NPCHit25, i * 16 /*0x10*/, j * 16 /*0x10*/);
    else
      SoundEngine.PlaySound(0, i * 16 /*0x10*/, j * 16 /*0x10*/);
  }

  private static void KillWall_DropItems(int i, int j, Tile tileCache)
  {
    int itemDrops = WorldGen.KillWall_GetItemDrops(tileCache);
    if (itemDrops <= 0)
      return;
    Item.NewItem(WorldGen.GetItemSource_FromWallBreak(i, j), i * 16 /*0x10*/, j * 16 /*0x10*/, 16 /*0x10*/, 16 /*0x10*/, itemDrops);
  }

