  public static void LaunchRocket(int x, int y, bool fromWiring)
  {
    int frameY = (int) Main.tile[x, y].frameY;
    int num = 0;
    while (frameY >= 40)
    {
      frameY -= 40;
      ++num;
    }
    if (frameY == 18)
      --y;
    Vector2 vector2 = new Vector2((float) (x * 16 /*0x10*/ + 8), (float) (y * 16 /*0x10*/ + 4));
    int Type = 167 + num;
    int Damage = 150;
    int KnockBack = 7;
    int index = Projectile.NewProjectile(WorldGen.GetProjectileSource_PlayerOrWires(x, y, fromWiring, Main.LocalPlayer), vector2.X, vector2.Y + 2f, 0.0f, -8f, Type, Damage, (float) KnockBack, Main.myPlayer);
    Main.projectile[index].originatedFromActivableTile = true;
    Main.tile[x, y].active(false);
    Main.tile[x, y + 1].active(false);
    NetMessage.SendTileSquare(-1, x, y, 1, 2);
  }

  public static void LaunchRocketSmall(int x, int y, bool fromWiring)
  {
    if (Main.tile[x, y].frameX == (short) 18)
      --x;
    if (Main.tile[x, y].frameY == (short) 18)
      --y;
    Vector2 vector2 = new Vector2((float) (x * 16 /*0x10*/ + 16 /*0x10*/), (float) (y * 16 /*0x10*/));
    int Type = 415 + Main.rand.Next(4);
    int Damage = 0;
    int KnockBack = 0;
    int index = Projectile.NewProjectile(WorldGen.GetProjectileSource_PlayerOrWires(x, y, fromWiring, Main.LocalPlayer), vector2.X, vector2.Y + 2f, 0.0f, -8f, Type, Damage, (float) KnockBack, Main.myPlayer);
    Main.projectile[index].originatedFromActivableTile = true;
  }

  public static bool CanKillTile(int i, int j, WorldGen.SpecialKillTileContext context)
  {
    if (context == WorldGen.SpecialKillTileContext.MowingTheGrass)
    {
      Tile tile = Main.tile[i, j];
      if (tile == null)
        return false;
      if (tile.type == (ushort) 2 || tile.type == (ushort) 109)
        return true;
    }
    return WorldGen.CanKillTile(i, j);
  }

  public static bool CanKillTile(int i, int j) => WorldGen.CanKillTile(i, j, out bool _);

  public static bool CanKillTile(int i, int j, out bool blockDamaged)
  {
    blockDamaged = false;
    if (i < 0 || j < 0 || i >= Main.maxTilesX || j >= Main.maxTilesY)
      return false;
    Tile t = Main.tile[i, j];
    Tile tile = (Tile) null;
    if (t == null || !t.active() || t.wall == (ushort) 350)
      return false;
    if (j >= 1)
      tile = Main.tile[i, j - 1];
    if (tile != null && tile.active())
    {
      int type = (int) tile.type;
      if (TileID.Sets.IsATreeTrunk[type] && (int) t.type != type && (tile.frameX != (short) 66 || tile.frameY < (short) 0 || tile.frameY > (short) 44) && (tile.frameX != (short) 88 || tile.frameY < (short) 66 || tile.frameY > (short) 110) && tile.frameY < (short) 198)
        return false;
      switch (type)
      {
        case 21:
        case 26:
        case 72:
        case 77:
        case 88:
        case 467:
        case 488:
          if ((int) t.type != type)
            return false;
          break;
        case 80 /*0x50*/:
          if ((int) t.type != type)
          {
            switch ((int) tile.frameX / 18)
            {
              case 0:
              case 1:
              case 4:
              case 5:
                return false;
            }
          }
          else
            break;
          break;
        case 323:
          if ((int) t.type != type && (tile.frameX == (short) 66 || tile.frameX == (short) 220))
            return false;
          break;
      }
    }
    if (TileID.Sets.Boulders[(int) t.type] && WorldGen.CheckBoulderChest(i, j))
    {
      blockDamaged = true;
      return false;
    }
    switch (t.type)
    {
      case 10:
        if (WorldGen.IsLockedDoor(t))
        {
          blockDamaged = true;
          return false;
        }
        break;
      case 21:
      case 467:
        if (!Chest.CanDestroyChest(i - (int) t.frameX / 18 % 2, j - (int) t.frameY / 18))
          return false;
        break;
      case 88:
        if (!Chest.CanDestroyChest(i - (int) t.frameX / 18 % 3, j - (int) t.frameY / 18))
          return false;
        break;
      case 235:
        int num = i - (int) t.frameX % 54 / 18;
        for (int index = 0; index < 3; ++index)
        {
          Tile target = Main.tile[num + index, j - 1];
          if (target.active() && WorldGen.CheckTileBreakability_HasReasonToReturnEarly((int) t.type, target, true))
          {
            blockDamaged = true;
            return false;
          }
        }
        break;
    }
    return true;
  }

  public static bool IsTileReplacable(int x, int y)
  {
    Tile tile1 = Main.tile[x, y];
    if (y >= 1)
    {
      Tile tile2 = Main.tile[x, y - 1];
      if (tile1 == null || tile2 == null)
        return false;
      if (tile2.active())
      {
        if (tile2.type == (ushort) 80 /*0x50*/ || tile2.type == (ushort) 488)
          return false;
        if (TileID.Sets.PreventsTileReplaceIfOnTopOfIt[(int) tile2.type] && (int) tile1.type != (int) tile2.type)
          return TileID.Sets.IsATreeTrunk[(int) tile2.type] ? tile2.frameX == (short) 66 && tile2.frameY >= (short) 0 && tile2.frameY <= (short) 44 || tile2.frameX == (short) 88 && tile2.frameY >= (short) 66 && tile2.frameY <= (short) 110 || tile2.frameY >= (short) 198 : tile2.type == (ushort) 323 && tile2.frameX != (short) 66 && tile2.frameX != (short) 220;
      }
    }
    return true;
  }

  public static int CheckTileBreakability(int x, int y)
  {
    if (Main.tile[x, y] == null)
      Main.tile[x, y] = new Tile();
    Tile t1 = Main.tile[x, y];
    if (y >= 1 && y <= Main.maxTilesY - 1)
    {
      if (Main.tile[x, y - 1] == null)
        Main.tile[x, y - 1] = new Tile();
      if (Main.tile[x, y + 1] == null)
        Main.tile[x, y + 1] = new Tile();
      Tile target1 = Main.tile[x, y - 1];
      Tile t2 = Main.tile[x, y + 1];
      if (t2 != null && t2.active() && WorldGen.IsLockedDoor(t2))
        return 2;
      if (!Main.tileSolid[(int) t1.type] && !Main.tileSolidTop[(int) t1.type])
        return 0;
      if (target1.active())
      {
        bool flag = WorldGen.IsAContainer(t1);
        if (WorldGen.CheckTileBreakability_HasReasonToReturnEarly((int) t1.type, target1, !flag))
          return TileID.Sets.IsATreeTrunk[(int) target1.type] ? (target1.frameX == (short) 66 && target1.frameY >= (short) 0 && target1.frameY <= (short) 44 || target1.frameX == (short) 88 && target1.frameY >= (short) 66 && target1.frameY <= (short) 110 || target1.frameY >= (short) 198 ? 0 : 2) : (target1.type == (ushort) 323 && target1.frameX != (short) 66 && target1.frameX != (short) 220 ? 0 : 2);
        if (target1.type == (ushort) 80 /*0x50*/ && (int) target1.type != (int) t1.type)
        {
          switch ((int) target1.frameX / 18)
          {
            case 0:
            case 1:
            case 4:
            case 5:
              return 2;
          }
        }
        if (t1.type == (ushort) 10 && WorldGen.IsLockedDoor(t1))
          return 1;
        if (TileID.Sets.Boulders[(int) t1.type])
          return WorldGen.CheckBoulderChest(x, y) ? 1 : 0;
      }
      if (t1.type == (ushort) 235)
      {
        int frameX = (int) t1.frameX;
        int num = x - frameX % 54 / 18;
        for (int index = 0; index < 3; ++index)
        {
          Tile target2 = Main.tile[num + index, y - 1];
          if (target2.active() && WorldGen.CheckTileBreakability_HasReasonToReturnEarly((int) t1.type, target2, true))
            return 2;
        }
      }
    }
    return 0;
  }

  private static bool CheckTileBreakability_HasReasonToReturnEarly(
    int ignoreType,
    Tile target,
    bool scanForContainer)
  {
    return ignoreType != (int) target.type && (target.type == (ushort) 77 && !Main.hardMode || TileID.Sets.PreventsTileRemovalIfOnTopOfIt[(int) target.type]) || WorldGen.IsLockedDoor(target) || scanForContainer && WorldGen.IsAContainer(target);
  }

  public static bool CheckTileBreakability2_ShouldTileSurvive(int x, int y)
  {
    if (Main.netMode == 1)
      return false;
    if (Main.tile[x, y] == null)
      Main.tile[x, y] = new Tile();
    Tile tile = Main.tile[x, y];
    if (TileID.Sets.BasicChest[(int) tile.type])
    {
      int num = (int) tile.frameX / 18;
      int Y = y - (int) tile.frameY / 18;
      while (num > 1)
        num -= 2;
      if (!Chest.DestroyChest(x - num, Y))
        return true;
    }
    if (tile.type == (ushort) 88)
    {
      int num1 = (int) tile.frameX / 18;
      int Y = y - (int) tile.frameY / 18;
      int num2 = num1 % 3;
      if (!Chest.DestroyChest(x - num2, Y))
        return true;
    }
    if (tile.type == (ushort) 470)
      return !TEDisplayDoll.IsBreakable(x, y);
    return tile.type == (ushort) 475 && !TEHatRack.IsBreakable(x, y);
  }

  public static bool ReplaceWall(int x, int y, ushort targetWall)
  {
    if ((int) targetWall >= (int) WallID.Count)
      return false;
    Tile tileCache = Main.tile[x, y];
    if (tileCache.wall == (ushort) 0 || targetWall == (ushort) 0 || tileCache.wall == (ushort) 350 || WorldGen.KillWall_CheckFailure(false, tileCache))
      return false;
    int num = 10;
    for (int index = 0; index < num; ++index)
      WorldGen.KillWall_MakeWallDust(x, y, tileCache);
    WorldGen.KillWall_PlaySounds(x, y, tileCache);
    WorldGen.KillWall_DropItems(x, y, tileCache);
    tileCache.wall = targetWall;
    tileCache.ClearWallPaintAndCoating();
    WorldGen.SquareWallFrame(x, y);
    return true;
  }

  public static bool ReplaceTile(int x, int y, int targetType, int targetStyle)
  {
    Tile tileSafely = Framing.GetTileSafely(x, y);
    if (!WorldGen.WouldTileReplacementWork(targetType, x, y) || !WorldGen.IsTileReplacable(x, y))
      return false;
    WorldGen.MoveReplaceTileAnchor(ref x, ref y, targetType, tileSafely);
    int tileDustAmount = WorldGen.KillTile_GetTileDustAmount(false, tileSafely);
    for (int index = 0; index < tileDustAmount; ++index)
      WorldGen.KillTile_MakeTileDust(x, y, tileSafely);
    WorldGen.KillTile_PlaySounds(x, y, false, tileSafely);
    WorldGen.KillTile_DropItems(x, y, tileSafely, true);
    WorldGen.AttemptFossilShattering(x, y, tileSafely, false);
    WorldGen.ReplaceTile_DoActualReplacement(targetType, targetStyle, x, y, tileSafely);
    return true;
  }

  private static void ReplaceTile_DoActualReplacement(
    int targetType,
    int targetStyle,
    int topLeftX,
    int topLeftY,
    Tile t)
  {
    if (TileID.Sets.BasicChest[targetType])
    {
      if (WorldGen.IsChestRigged(topLeftX, topLeftY) && Main.netMode != 1)
      {
        Wiring.HitSwitch(topLeftX, topLeftY);
        NetMessage.SendData(59, number: topLeftX, number2: (float) topLeftY);
      }
      WorldGen.ReplaceTile_DoActualReplacement_Area(targetType, targetStyle, topLeftX, topLeftY, 2, 2);
    }
    else if (TileID.Sets.BasicDresser[targetType])
      WorldGen.ReplaceTile_DoActualReplacement_Area(targetType, targetStyle, topLeftX, topLeftY, 3, 2);
    else if (TileID.Sets.Campfires[targetType])
    {
      bool flag = t.frameY >= (short) 36;
      WorldGen.ReplaceTile_DoActualReplacement_Area(targetType, targetStyle, topLeftX, topLeftY, 3, 2, frameOffsetY: flag ? 36 : 0);
    }
    else
      WorldGen.ReplaceTile_DoActualReplacement_Single(targetType, targetStyle, topLeftX, topLeftY, t);
  }

  private static void ReplaceTile_DoActualReplacement_Single(
    int targetType,
    int targetStyle,
    int topLeftX,
    int topLeftY,
    Tile t)
  {
    WorldGen.ReplaceTile_EliminateNaturalExtras(topLeftX, topLeftY);
    int type = (int) t.type;
    t.type = (ushort) targetType;
    if (TileID.Sets.Platforms[(int) t.type] || t.type == (ushort) 380)
      t.frameY = (short) (targetStyle * 18);
    if (TileID.Sets.Torches[(int) t.type])
      t.frameY = (short) (targetStyle * 22);
    t.ClearBlockPaintAndCoating();
    bool flag = !WorldGen.CanPoundTile(topLeftX, topLeftY);
    if (TileID.Sets.Platforms[type] && TileID.Sets.Platforms[(int) t.type])
      flag = false;
    if (flag)
    {
      t.slope((byte) 0);
      t.halfBrick(false);
    }
    if (t.type == (ushort) 53 || t.type == (ushort) 396 || t.type == (ushort) 397)
    {
      if (SpecialSeedFeatures.RainbowSandAndBlackSandWalls)
        t.color(WorldGen.GetRainbowPaintIDForPosition(topLeftX, topLeftY, true));
      else if (Main.tenthAnniversaryWorld && !Main.remixWorld && !Main.notTheBeesWorld && !Main.dontStarveWorld)
        t.color((byte) 7);
    }
    if (TileID.Sets.TruncatesWalls[targetType] != TileID.Sets.TruncatesWalls[type])
      WorldGen.SquareWallFrame(topLeftX, topLeftY);
    WorldGen.SquareTileFrame(topLeftX, topLeftY);
  }

  private static void ReplaceTile_EliminateNaturalExtras(int x, int y)
  {
    if (!WorldGen.InWorld(x, y, 2))
      return;
    if (Main.tile[x, y - 1] != null && Main.tile[x, y - 1].active() && (TileID.Sets.ReplaceTileBreakUp[(int) Main.tile[x, y - 1].type] || Main.tile[x, y - 1].type == (ushort) 165 && (Main.tile[x, y - 1].frameY == (short) 36 || Main.tile[x, y - 1].frameY == (short) 54 || Main.tile[x, y - 1].frameY == (short) 90)))
      WorldGen.KillTile(x, y - 1);
    if (Main.tile[x, y + 1] == null || !Main.tile[x, y + 1].active() || !TileID.Sets.ReplaceTileBreakDown[(int) Main.tile[x, y + 1].type] && (Main.tile[x, y + 1].type != (ushort) 165 || Main.tile[x, y + 1].frameY != (short) 0 && Main.tile[x, y + 1].frameY != (short) 18 && Main.tile[x, y + 1].frameY != (short) 72))
      return;
    WorldGen.KillTile(x, y + 1);
  }

  private static void ReplaceTile_DoActualReplacement_Area(
    int targetType,
    int targetStyle,
    int topLeftX,
    int topLeftY,
    int areaSizeX,
    int areaSizeY,
    int frameOffsetX = 0,
    int frameOffsetY = 0)
  {
    for (int index1 = 0; index1 < areaSizeX; ++index1)
    {
      for (int index2 = 0; index2 < areaSizeY; ++index2)
      {
        Tile tile = Main.tile[topLeftX + index1, topLeftY + index2];
        tile.type = (ushort) targetType;
        tile.frameX = (short) (targetStyle * (areaSizeX * 18) + index1 * 18 + frameOffsetX);
        tile.frameY = (short) (index2 * 18 + frameOffsetY);
        tile.ClearBlockPaintAndCoating();
      }
    }
    for (int index3 = 0; index3 < areaSizeX; ++index3)
    {
      for (int index4 = 0; index4 < areaSizeY; ++index4)
        WorldGen.SquareTileFrame(topLeftX + index3, topLeftY + index4);
    }
  }

  private static void MoveReplaceTileAnchor(ref int x, ref int y, int targetType, Tile t)
  {
    if (TileID.Sets.BasicChest[(int) t.type])
    {
      x -= (int) t.frameX % 36 / 18;
      y -= (int) t.frameY % 36 / 18;
    }
    if (TileID.Sets.BasicDresser[(int) t.type])
    {
      x -= (int) t.frameX % 54 / 18;
      y -= (int) t.frameY % 36 / 18;
    }
    if (!TileID.Sets.Campfires[(int) t.type])
      return;
    x -= (int) t.frameX % 54 / 18;
    y -= (int) t.frameY % 36 / 18;
  }

  public static bool WouldTileReplacementWork(int attemptingToReplaceWith, int x, int y)
  {
    Tile t = Main.tile[x, y];
    if (attemptingToReplaceWith >= (int) TileID.Count || TileID.Sets.Conversion.Grass[attemptingToReplaceWith] || attemptingToReplaceWith == 633)
      return false;
    if (Main.tileRope[(int) t.type] && WorldGen.InWorld(x, y, 2))
    {
      Tile tile1 = Main.tile[x - 1, y];
      Tile tile2 = Main.tile[x + 1, y];
      if (attemptingToReplaceWith == 314 && tile1 != null && tile2 != null && (tile1.active() && tile1.type == (ushort) 314 || tile2.active() && tile2.type == (ushort) 314) || TileID.Sets.Platforms[attemptingToReplaceWith] && tile1 != null && tile2 != null && (tile1.active() && TileID.Sets.Platforms[(int) tile1.type] || tile2.active() && TileID.Sets.Platforms[(int) tile2.type]) || attemptingToReplaceWith == 380 && tile1 != null && tile2 != null && (tile1.active() && tile1.type == (ushort) 380 || tile2.active() && tile2.type == (ushort) 380))
        return true;
    }
    bool flag1 = !WorldGen.ReplaceTile_IsValidSolid(attemptingToReplaceWith) || !WorldGen.ReplaceTile_IsValidSolid((int) t.type);
    bool flag2 = !WorldGen.ReplaceTile_IsValidTorch(attemptingToReplaceWith) || !WorldGen.ReplaceTile_IsValidTorch((int) t.type);
    bool flag3 = !WorldGen.ReplaceTile_IsValidCampfire(attemptingToReplaceWith) || !WorldGen.ReplaceTile_IsValidCampfire((int) t.type);
    int num1 = !WorldGen.ReplaceTile_IsValidPlatform(attemptingToReplaceWith) ? 1 : (!WorldGen.ReplaceTile_IsValidPlatform((int) t.type) ? 1 : 0);
    bool flag4 = !WorldGen.ReplaceTile_IsValidSolid(attemptingToReplaceWith) && !WorldGen.ReplaceTile_IsValidPlatform(attemptingToReplaceWith) || !WorldGen.ReplaceTile_IsValidSolid((int) t.type) && !WorldGen.ReplaceTile_IsValidPlatform((int) t.type);
    bool flag5 = !WorldGen.ReplaceTile_IsValidChest(attemptingToReplaceWith) || !WorldGen.ReplaceTile_IsValidChest((int) t.type) || Chest.IsLocked(t);
    bool flag6 = !WorldGen.ReplaceTile_IsValidDresser(attemptingToReplaceWith) || !WorldGen.ReplaceTile_IsValidDresser((int) t.type);
    int num2 = flag2 ? 1 : 0;
    return (num1 & num2 & (flag3 ? 1 : 0) & (flag1 ? 1 : 0) & (flag4 ? 1 : 0) & (flag5 ? 1 : 0) & (flag6 ? 1 : 0)) == 0;
  }

  private static bool ReplaceTile_IsValidSolid(int type)
  {
    if (!Main.tileSolid[type] || Main.tileSolidTop[type])
      return false;
    return Main.tileRope[type] || !Main.tileFrameImportant[type];
  }

