  private static void ShakeTree(int i, int j)
  {
    if (WorldGen.numTreeShakes == WorldGen.maxTreeShakes)
      return;
    int bottomX;
    int bottomY;
    TreeTypes typeAndTreeBottom = WorldGen.GetTreeTypeAndTreeBottom(i, j, out bottomX, out bottomY);
    int index1 = bottomY;
    if (typeAndTreeBottom == TreeTypes.None)
      return;
    for (int index2 = 0; index2 < WorldGen.numTreeShakes; ++index2)
    {
      if (WorldGen.treeShakeX[index2] == bottomX && WorldGen.treeShakeY[index2] == bottomY)
        return;
    }
    WorldGen.treeShakeX[WorldGen.numTreeShakes] = bottomX;
    WorldGen.treeShakeY[WorldGen.numTreeShakes] = bottomY;
    ++WorldGen.numTreeShakes;
    --bottomY;
    while (bottomY > 10 && Main.tile[bottomX, bottomY].active() && TileID.Sets.IsShakeable[(int) Main.tile[bottomX, bottomY].type])
      --bottomY;
    ++bottomY;
    if (!WorldGen.IsTileALeafyTreeTop(bottomX, bottomY) || Collision.SolidTiles(bottomX - 2, bottomX + 2, bottomY - 2, bottomY + 2))
      return;
    int maxValue = 17;
    int Type1 = 28;
    if (Main.tenthAnniversaryWorld && !Main.remixWorld)
    {
      maxValue *= 2;
      Type1 = 75;
    }
    if (Main.tenthAnniversaryWorld && Main.notTheBeesWorld && !Main.drunkWorld && WorldGen.genRand.Next(50) == 0)
    {
      int Stack = Main.rand.Next(12, 21);
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(i, j), i * 16 /*0x10*/, j * 16 /*0x10*/, 16 /*0x10*/, 16 /*0x10*/, 1130, Stack);
    }
    else if (Main.getGoodWorld && WorldGen.genRand.Next(maxValue) == 0)
      Projectile.NewProjectile((IEntitySource) WorldGen.GetProjectileSource_ShakeTree(bottomX, bottomY), (float) (bottomX * 16 /*0x10*/), (float) (bottomY * 16 /*0x10*/), (float) Main.rand.Next(-100, 101) * (1f / 500f), 0.0f, Type1, 0, 0.0f, Main.myPlayer, 16f, 16f);
    else if (WorldGen.genRand.Next(300) == 0 && typeAndTreeBottom == TreeTypes.Forest)
      Item.NewItem((IEntitySource) WorldGen.GetItemSource_ShakeTree(bottomX, bottomY), bottomX * 16 /*0x10*/, bottomY * 16 /*0x10*/, 16 /*0x10*/, 16 /*0x10*/, 832);
    else if (WorldGen.genRand.Next(300) == 0 && typeAndTreeBottom == TreeTypes.Forest)
      Item.NewItem((IEntitySource) WorldGen.GetItemSource_ShakeTree(bottomX, bottomY), bottomX * 16 /*0x10*/, bottomY * 16 /*0x10*/, 16 /*0x10*/, 16 /*0x10*/, 933);
    else if (WorldGen.genRand.Next(200) == 0 && typeAndTreeBottom == TreeTypes.Jungle)
      Item.NewItem((IEntitySource) WorldGen.GetItemSource_ShakeTree(bottomX, bottomY), bottomX * 16 /*0x10*/, bottomY * 16 /*0x10*/, 16 /*0x10*/, 16 /*0x10*/, 3360);
    else if (WorldGen.genRand.Next(200) == 0 && typeAndTreeBottom == TreeTypes.Jungle)
      Item.NewItem((IEntitySource) WorldGen.GetItemSource_ShakeTree(bottomX, bottomY), bottomX * 16 /*0x10*/, bottomY * 16 /*0x10*/, 16 /*0x10*/, 16 /*0x10*/, 3361);
    else if (WorldGen.genRand.Next(1000) == 0 && typeAndTreeBottom == TreeTypes.Forest)
