    else if (WorldGen.genRand.Next(1000) == 0 && typeAndTreeBottom == TreeTypes.Forest)
      Item.NewItem((IEntitySource) WorldGen.GetItemSource_ShakeTree(bottomX, bottomY), bottomX * 16 /*0x10*/, bottomY * 16 /*0x10*/, 16 /*0x10*/, 16 /*0x10*/, 4366);
    else if (WorldGen.genRand.Next(100) == 0 && (typeAndTreeBottom == TreeTypes.Forest || typeAndTreeBottom == TreeTypes.Snow || typeAndTreeBottom == TreeTypes.Hallowed || typeAndTreeBottom == TreeTypes.Ash))
