  public static void CheckExploitDestroyQueue()
  {
    if (WorldGen.destroyObject)
      return;
    while (WorldGen.ExploitDestroyQueue.Count > 0)
    {
      Point point = WorldGen.ExploitDestroyQueue.Dequeue();
      if (Framing.GetTileSafely(point.X, point.Y).active())
      {
        WorldGen.SquareTileFrame(point.X, point.Y);
        if (Main.netMode != 0)
          NetMessage.SendTileSquare(-1, point.X, point.Y);
      }
    }
  }

  private static Player GetPlayerForTile(int x, int y)
  {
    return Main.player[(int) Player.FindClosest(new Vector2((float) x, (float) y) * 16f, 16 /*0x10*/, 16 /*0x10*/)];
  }

  public static void KillTile_DropItems(
    int x,
    int y,
    Tile tileCache,
    bool includeLargeObjectDrops = false)
  {
    int dropItem;
    int dropItemStack;
    int secondaryItem;
    int secondaryItemStack;
    bool noPrefix;
    WorldGen.KillTile_GetItemDrops(x, y, tileCache, out dropItem, out dropItemStack, out secondaryItem, out secondaryItemStack, out noPrefix, includeLargeObjectDrops);
    if (Main.getGoodWorld && !tileCache.active())
      return;
    if (dropItem > 0)
      Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, y), x * 16 /*0x10*/, y * 16 /*0x10*/, 16 /*0x10*/, 16 /*0x10*/, dropItem, dropItemStack, pfix: noPrefix ? -4 : -1);
    if (secondaryItem <= 0)
      return;
    Item.NewItem(WorldGen.GetItemSource_FromTileBreak(x, y), x * 16 /*0x10*/, y * 16 /*0x10*/, 16 /*0x10*/, 16 /*0x10*/, secondaryItem, secondaryItemStack, pfix: noPrefix ? -4 : -1);
  }

