  private static void SetGemTreeDrops(
    int gemType,
    int seedType,
    Tile tileCache,
    ref int dropItem,
    ref int secondaryItem)
  {
    dropItem = Main.rand.Next(10) != 0 ? 3 : gemType;
    if (tileCache.frameX < (short) 22 || tileCache.frameY < (short) 198 || Main.rand.Next(2) != 0)
      return;
    secondaryItem = seedType;
  }

  private static void SetVanityTreeDrops(int dropType, Tile tileCache, ref int dropItem)
  {
    if (Main.rand.Next(2) != 0)
      return;
    dropItem = dropType;
  }

  public static bool IsHarvestableHerbWithSeed(int type, int style, int y)
  {
    if (type == 82 || type != 84 && type != 83)
      return false;
    bool flag = false;
    if (type == 84)
      flag = true;
    if (WorldGen.IsAlchemyPlantHarvestable(style, y))
      flag = true;
    return flag;
  }

  public static bool IsAlchemyPlantHarvestable(int style, int y)
  {
    return style == 0 && Main.dayTime || style == 1 && !Main.dayTime || style == 3 && !Main.dayTime && (Main.bloodMoon || Main.moonPhase == 0) || style == 4 && (Main.raining || (double) Main.cloudAlpha > 0.0) || style == 5 && (!Main.raining || (Main.remixWorld ? (y < GenVars.remixSurfaceLayerHigh ? 1 : 0) : ((double) y > Main.worldSurface ? 1 : 0)) != 0) && Main.time > 40500.0;
  }

  private static bool KillTile_ShouldDropSeeds(int x, int y)
  {
    if (Main.rand.Next(2) != 0)
      return false;
    return WorldGen.GetPlayerForTile(x, y).HasItem(281) || WorldGen.GetPlayerForTile(x, y).HasItem(986);
  }

  private static void KillTile_GetTreeDrops(
    int i,
    int j,
    Tile tileCache,
    ref bool dropIsWood,
    ref bool bonusWood,
    ref int dropItem,
    ref int secondaryItem)
  {
    if (tileCache.frameX >= (short) 22 && tileCache.frameY >= (short) 198)
    {
      if (Main.netMode != 1)
      {
        if (WorldGen.genRand.Next(2) == 0)
        {
          if (WorldGen.TreeTypeDropsAcorns(WorldGen.GetTreeType(i, j)))
          {
            dropItem = 9;
            secondaryItem = 27;
          }
          else
            dropItem = 9;
        }
        else
          dropItem = 9;
      }
    }
    else
      dropItem = 9;
    if (dropItem != 9)
      return;
    dropIsWood = true;
    int bottomX;
    int bottomY;
    switch (WorldGen.GetTreeTypeAndTreeBottom(i, j, out bottomX, out bottomY))
    {
      case TreeTypes.Corrupt:
        dropItem = 619;
        break;
      case TreeTypes.Mushroom:
        dropItem = WorldGen.genRand.Next(2) != 0 ? 0 : 183;
        break;
      case TreeTypes.Crimson:
        dropItem = 911;
        break;
      case TreeTypes.Jungle:
        dropItem = 620;
        break;
      case TreeTypes.Snow:
        dropItem = 2503;
        break;
      case TreeTypes.Hallowed:
        dropItem = 621;
        break;
      case TreeTypes.Ash:
        dropItem = 5215;
        break;
