  public static void GetRopeEnds(
    int x,
    int y,
    out int topRopeY,
    out int bottomRopeY,
    bool treatEmptyAsTheRopeEnd = false,
    int rangeToCheck = 5)
  {
    topRopeY = -1;
    bottomRopeY = -1;
    for (int index = 1; index <= rangeToCheck && WorldGen.InWorld(x, y - index); ++index)
    {
      Tile tile = Main.tile[x, y - index];
      if (tile != null)
      {
        if (!tile.active())
        {
          if (treatEmptyAsTheRopeEnd)
          {
            topRopeY = y - index;
            break;
          }
          break;
        }
        if (Main.tileRope[(int) tile.type])
        {
          topRopeY = y - index;
          break;
        }
      }
      else
        break;
    }
    for (int index = 1 + (y - topRopeY); index <= rangeToCheck + 1 && WorldGen.InWorld(x, topRopeY + index); ++index)
    {
      Tile tile = Main.tile[x, topRopeY + index];
      if (tile == null)
        break;
      if (!tile.active())
      {
        if (!treatEmptyAsTheRopeEnd)
          break;
        bottomRopeY = topRopeY + index;
        break;
      }
      if (Main.tileRope[(int) tile.type])
      {
        bottomRopeY = topRopeY + index;
        break;
      }
    }
  }

  public static bool IsRope(int x, int y, int rangeToCheck = 5)
  {
