  }

  public static bool IsRope(
    int x,
    int y,
    out int topRopeY,
    out int bottomRopeY,
    int rangeToCheck = 5)
  {
    topRopeY = -1;
    bottomRopeY = -1;
    Tile tile = Main.tile[x, y];
    if (tile == null || !tile.active())
      return false;
    if (Main.tileRope[(int) tile.type])
      return true;
    if (tile.type != (ushort) 314 && tile.type != (ushort) 380 && !TileID.Sets.Platforms[(int) tile.type])
      return false;
    WorldGen.GetRopeEnds(x, y, out topRopeY, out bottomRopeY, rangeToCheck: rangeToCheck);
    return topRopeY != -1 && bottomRopeY != -1;
  }

