  public static bool AnyLiquidAt(int x, int y, int range, int liquidType = -1)
  {
    if (range <= 0)
      return WorldGen.AnyLiquidAt(x, y, liquidType);
    int val1 = 5;
    int num1 = Math.Max(val1, x - range);
    int num2 = Math.Max(val1, y - range);
    int num3 = Math.Min(Main.maxTilesX - val1, x + range);
    int num4 = Math.Min(Main.maxTilesY - val1, y + range);
    for (int x1 = num1; x1 < num3; ++x1)
    {
      for (int y1 = num2; y1 < num4; ++y1)
      {
        if (WorldGen.AnyLiquidAt(x1, y1, liquidType))
          return true;
      }
    }
    return false;
  }

