      ++num2;
    }
    while (num2 < 2);
    WorldGen.AddUpAlignmentCounts();
    if (X != Main.maxTilesX - 1)
      return;
    WorldGen.Skyblock.Calculate();
  }

  public static void AddUpAlignmentCounts(bool clearCounts = false)
  {
    if (clearCounts)
    {
      WorldGen.totalEvil2 = 0;
      WorldGen.totalSolid2 = 0;
      WorldGen.totalGood2 = 0;
      WorldGen.totalBlood2 = 0;
    }
    int num1 = 0;
    int num2 = 0;
    int num3 = 0;
    for (int index = 0; index < TileID.Sets.HallowCountCollection.Count; ++index)
    {
      int tileCount = WorldGen.tileCounts[TileID.Sets.HallowCountCollection[index]];
      WorldGen.totalGood2 += tileCount;
      num1 += tileCount;
    }
    for (int index = 0; index < TileID.Sets.CorruptCountCollection.Count; ++index)
    {
      int tileCount = WorldGen.tileCounts[TileID.Sets.CorruptCountCollection[index]];
      WorldGen.totalEvil2 += tileCount;
      num2 += tileCount;
    }
    for (int index = 0; index < TileID.Sets.CrimsonCountCollection.Count; ++index)
    {
      int tileCount = WorldGen.tileCounts[TileID.Sets.CrimsonCountCollection[index]];
      WorldGen.totalBlood2 += tileCount;
      num3 += tileCount;
    }
    if (Main.remixWorld)
    {
      int tileCount1 = WorldGen.tileCounts[474];
      WorldGen.totalEvil2 += tileCount1;
      num2 += tileCount1;
      int tileCount2 = WorldGen.tileCounts[195];
      WorldGen.totalBlood2 += tileCount2;
      num3 += tileCount2;
    }
    WorldGen.totalSolid2 += WorldGen.tileCounts[2] + WorldGen.tileCounts[477] + WorldGen.tileCounts[1] + WorldGen.tileCounts[60] + WorldGen.tileCounts[53] + WorldGen.tileCounts[161];
    WorldGen.totalSolid2 += num1;
    WorldGen.totalSolid2 += num2;
    WorldGen.totalSolid2 += num3;
    Array.Clear((Array) WorldGen.tileCounts, 0, WorldGen.tileCounts.Length);
  }

