      if (player.active && !player.dead)
      {
        Point size = new Point(24, 24);
        Microsoft.Xna.Framework.Rectangle rectangle1 = Utils.CenteredRectangle(player.Center.ToTileCoordinates(), size);
        Microsoft.Xna.Framework.Rectangle rectangle2 = rectangle1;
        double num2 = Utils.Clamp<double>((double) player.velocity.X, -5.75, 5.75);
        rectangle2.Offset(new Point((int) (num2 * 60.0 / 16.0), 0));
        Microsoft.Xna.Framework.Rectangle rectangle3 = Microsoft.Xna.Framework.Rectangle.Union(rectangle1, rectangle2);
        thunderStormSafeSpots.Add(rectangle3);
      }
    }
    for (int index = 0; index < (int) byte.MaxValue; ++index)
    {
      Player player = Main.player[index];
      if (player.active && !player.dead && player.ZoneRain && !player.ZoneSnow && player.afkCounter < Player.AFKTimeNeededForNoLuckyStars)
      {
        int maxValue = num1;
        if (player.sleeping.isSleeping)
          maxValue *= 2;
        if (player.HeldItem.fishingPole > 0)
          maxValue *= 2;
        if (Main.rand.Next(maxValue) == 0)
          WorldGen.SpawnStormLightningNearPlayer(thunderStormSafeSpots, player);
      }
    }
  }

  private static void SpawnStormLightningNearPlayer(List<Microsoft.Xna.Framework.Rectangle> safespots, Player player)
  {
    Microsoft.Xna.Framework.Rectangle tileRectangle = Utils.CenteredRectangle(player.Center.ToTileCoordinates(), Point.Zero);
    tileRectangle.Inflate(Main.MaxWorldViewSize.X / 32 /*0x20*/, Main.MaxWorldViewSize.Y / 32 /*0x20*/);
    Microsoft.Xna.Framework.Rectangle world = WorldUtils.ClampToWorld(tileRectangle, 10);
    if (world.Width == 0 || world.Height == 0)
      return;
    for (int index = 0; index < 400; ++index)
    {
      int x = Main.rand.Next(world.Left, world.Right + 1);
      int y = Main.rand.Next(world.Top, world.Bottom + 1);
      Tile tile = Main.tile[x, y];
      while (y > 0 && WorldGen.IsLightningAttractor(Main.tile[x, y - 1]))
        tile = Main.tile[x, --y];
      if (index < 350)
      {
        if (!WorldGen.IsLightningAttractor(tile))
          continue;
      }
      else if (tile.liquid == (byte) 0 && !WorldGen.SolidTile(tile))
        continue;
      if (y <= 0 || Main.tile[x, y - 1].liquid == (byte) 0)
      {
        bool shouldSkipForThisPlayer = false;
        if (WorldGen.TrySpawnLightningBolt(safespots, x, y, ref shouldSkipForThisPlayer))
        {
          WorldGen.DebugLogLightning(index < 350 ? "attracted" : "spawned");
          return;
        }
        if (shouldSkipForThisPlayer)
        {
          WorldGen.DebugLogLightning("too close to existing strike");
          return;
        }
      }
    }
    WorldGen.DebugLogLightning("no target");
  }

  private static bool IsLightningAttractor(Tile tile)
  {
    if (!tile.nactive())
      return false;
    return TileID.Sets.GetsCheckedForLeaves[(int) tile.type] || TileID.Sets.AttractsStormLightning[(int) tile.type];
  }

  private static bool TrySpawnLightningBolt(
    List<Microsoft.Xna.Framework.Rectangle> safespots,
    int x,
    int y,
    ref bool shouldSkipForThisPlayer)
  {
    if (WorldGen.IsSafeFromRain(x, y - 1))
      return false;
    foreach (Microsoft.Xna.Framework.Rectangle safespot in safespots)
    {
      if (safespot.Contains(x, y))
        return false;
    }
    Vector2 Other = new Vector2((float) (x * 16 /*0x10*/ + 8), (float) (y * 16 /*0x10*/ + 2));
    for (int index = 0; index < 1000; ++index)
    {
      Projectile projectile = Main.projectile[index];
      if (projectile.active && projectile.type == 1091 && (double) projectile.Distance(Other) < 800.0)
      {
        shouldSkipForThisPlayer = true;
        return false;
      }
    }
    return WorldGen.TrySpawnLightningBolt(x, y);
  }

  public static bool TrySpawnLightningBolt(int x, int y)
  {
    int num1 = Main.rand.Next(Utils.MaxFloatInt + 1);
    int num2 = 2;
    if (Main.tile[x, y].liquid > (byte) 0)
      num2 += 16 /*0x10*/ * ((int) byte.MaxValue - (int) Main.tile[x, y].liquid) / (int) byte.MaxValue;
    Vector2 vector2 = new Vector2((float) (x * 16 /*0x10*/ + 8), (float) (y * 16 /*0x10*/ + num2));
    if (!LightningGenerator.StormLightning.CanHitTarget((uint) num1, vector2))
      return false;
    Projectile.NewProjectile((IEntitySource) new EntitySource_ByProjectileSourceId(22), vector2, Vector2.Zero, 1091, 500, 0.0f, Main.myPlayer, -1f, ai2: (float) num1);
    return true;
  }

  public static int GetWorldUpdateRate()
  {
    int worldUpdateRate = Math.Min(Main.desiredWorldTilesUpdateRate, 24);
    if (CreativePowerManager.Instance.GetPower<CreativePowers.FreezeTime>().Enabled)
      worldUpdateRate = 0;
    return worldUpdateRate;
  }

