        num5 = Main.maxTilesX;
      if (num6 < 0)
        num6 = 0;
      if (num7 > Main.maxTilesY)
        num7 = Main.maxTilesY;
      double num8 = num1 * (double) WorldGen.genRand.Next(80 /*0x50*/, 120) * 0.01;
      for (int x = num4; x < num5; ++x)
      {
        for (int y = num6; y < num7; ++y)
        {
          double num9 = Math.Abs((double) x - vector2D1.X);
          double num10 = Math.Abs((double) y - vector2D1.Y);
          if (Math.Sqrt(num9 * num9 + num10 * num10) < num8 * 0.4 && WorldGen.CanBeClearedDuringGeneration((int) Main.tile[x, y].type, x, y))
            Main.tile[x, y].active(false);
        }
      }
      vector2D1 = Vector2D.op_Addition(vector2D1, vector2D2);
      vector2D2.X += (double) WorldGen.genRand.Next(-10, 11) * 0.05;
      vector2D2.Y += (double) WorldGen.genRand.Next(-10, 11) * 0.05;
      if (vector2D2.X > (double) num2 + 0.5)
        vector2D2.X = (double) num2 + 0.5;
      if (vector2D2.X < (double) num2 - 0.5)
        vector2D2.X = (double) num2 - 0.5;
      if (vector2D2.Y > 0.0)
        vector2D2.Y = 0.0;
      if (vector2D2.Y < -0.5)
        vector2D2.Y = -0.5;
    }
  }

