    }
    for (int index = 0; index < LiquidBuffer.numLiquidBuffer; ++index)
    {
      LiquidBuffer liquidBuffer = Main.liquidBuffer[index];
      Main.tile[liquidBuffer.x, liquidBuffer.y].checkingLiquid(false);
    }
    Liquid.numLiquid = 0;
    LiquidBuffer.numLiquidBuffer = 0;
  }

