  public static bool CanPoundTile(int x, int y)
  {
    if (Main.tile[x, y] == null)
      Main.tile[x, y] = new Tile();
    if (Main.tile[x, y - 1] == null)
      Main.tile[x, y - 1] = new Tile();
    if (Main.tile[x, y + 1] == null)
      Main.tile[x, y + 1] = new Tile();
    switch (Main.tile[x, y].type)
    {
      case 10:
      case 48 /*0x30*/:
      case 137:
      case 232:
      case 380:
      case 387:
      case 388:
      case 476:
      case 484:
        return false;
      default:
        return (Main.tile[x, y].type < (ushort) 0 || !TileID.Sets.Boulders[(int) Main.tile[x, y].type]) && (!WorldGen.isGeneratingOrLoadingWorld || Main.tile[x, y].type != (ushort) 190 && Main.tile[x, y].type != (ushort) 30) && (!Main.tile[x, y - 1].active() || !WorldGen.ForbidsSloping(x, y - 1)) && WorldGen.CanKillTile(x, y);
    }
  }

  public static bool ForbidsSloping(int x, int y)
