  public static void CheckFoodPlatter(int x, int y, int type)
  {
    if (Main.tile[x, y] == null || WorldGen.destroyObject || WorldGen.SolidTileAllowBottomSlope(x, y + 1))
      return;
    TEFoodPlatter result;
    if (type == 520 && TileEntity.TryGetAt<TEFoodPlatter>(x, y, out result) && result.item.stack > 0)
    {
      result.DropItem();
      if (Main.netMode != 2)
        Main.LocalPlayer.InterruptItemUsageIfOverTile(520);
    }
    WorldGen.destroyObject = true;
    if ((int) Main.tile[x, y].type == type)
      WorldGen.KillTile(x, y);
    if (type == 520)
      TileEntityType<TEFoodPlatter>.Kill(x, y);
    WorldGen.destroyObject = false;
  }

  public static void HandleRopeEndFraming(int i, int j)
  {
    WorldGen.HandleRopeEndFraming_Inner(i, j);
    WorldGen._preventInfiniteRopeFraming = false;
  }

  private static void HandleRopeEndFraming_Inner(int i, int j)
  {
    if (WorldGen._preventInfiniteRopeFraming)
      return;
    WorldGen._preventInfiniteRopeFraming = true;
    if (!WorldGen.InWorld(i, j, 1))
      return;
    Tile tile1 = Main.tile[i, j - 1];
    Tile tile2 = Main.tile[i, j + 1];
    if (tile1 == null || tile2 == null)
      return;
    int num = !tile1.active() || tile1.type < (ushort) 0 ? 0 : (tile2.type == (ushort) 314 || TileID.Sets.Platforms[(int) tile1.type] || tile1.type == (ushort) 380 ? 1 : (Main.tileRope[(int) tile1.type] ? 1 : 0));
    bool flag = false;
    if (num == 0)
      flag = tile2.active() && tile2.type >= (ushort) 0 && (tile2.type == (ushort) 314 || TileID.Sets.Platforms[(int) tile2.type] || tile2.type == (ushort) 380 || Main.tileRope[(int) tile2.type]);
    if (num == 0 && !flag)
      return;
    int topRopeY = -1;
    int bottomRopeY = -1;
    WorldGen.GetRopeEnds(i, j, out topRopeY, out bottomRopeY, true);
    if (topRopeY != -1 && topRopeY != j)
      WorldGen.TileFrame(i, topRopeY);
    if (bottomRopeY == -1 || bottomRopeY == j)
      return;
    WorldGen.TileFrame(i, bottomRopeY);
  }

  public static void TileFrame(int i, int j, bool resetFrame = false, bool noBreak = false)
  {
    if (i <= 5 || j <= 5 || i >= Main.maxTilesX - 5 || j >= Main.maxTilesY - 5 || Main.tile[i, j] == null)
      return;
    MapUpdateQueue.Add(i, j);
    try
    {
      Tile tileCache = Main.tile[i, j];
      if (!tileCache.active())
      {
        tileCache.halfBrick(false);
        tileCache.ClearBlockPaintAndCoating();
        tileCache.slope((byte) 0);
      }
      if (tileCache.liquid > (byte) 0 && Main.netMode != 1 && !WorldGen.generatingWorld)
        Liquid.AddWater(i, j);
      if (!tileCache.active())
        return;
      int type = (int) tileCache.type;
      if (Main.tileFrameImportant[type])
      {
        if (noBreak && !TileID.Sets.Torches[type] && !TileID.Sets.FrameImportantEchoCulling[type])
          return;
        WorldGen.TileFrameImportant(i, j, type, tileCache, resetFrame);
      }
      else
      {
        if (!Main.tileSolid[type])
        {
          switch (type)
          {
            case 49:
              WorldGen.CheckOnTable1x1(i, j, (int) (byte) type);
              return;
            case 80 /*0x50*/:
              if (WorldGen.CheckCactus(i, j))
                return;
              break;
          }
          if (TileID.Sets.IsVine[type] && !WorldGen.CheckVines(i, j, type, tileCache))
            return;
        }
        if (WorldGen.generatingWorld || TileID.Sets.Falling[type] && WorldGen.SpawnFallingBlockProjectile(i, j, type, tileCache))
          return;
        WorldGen.TileFrameCosmetic(i, j, tileCache, resetFrame);
      }
    }
    catch
    {
    }
  }

  public static void TileFrameCosmetic(int i, int j, Tile tileCache, bool resetFrame = false)
