  private static bool SpawnFallingBlockProjectile(int i, int j, int type, Tile tileCache)
  {
    if (Main.netMode == 1)
      return false;
    Tile tileTopCache = Main.tile[i, j - 1];
    Tile tile = Main.tile[i, j + 1];
    if (tileCache == null || tileTopCache == null || tile == null || !WorldGen.BlockBelowMakesSandFall(i, j) || !WorldGen.AllowsSandfall(tileTopCache))
      return false;
    int projType;
    int dmg;
    WorldGen.GetSandfallProjData(type, out projType, out dmg);
    tileCache.ClearTile();
    if (Main.netMode == 0)
    {
      int index = Projectile.NewProjectile((IEntitySource) WorldGen.GetProjectileSource_TileBreak(i, j), (float) (i * 16 /*0x10*/ + 8), (float) (j * 16 /*0x10*/ + 8), 0.0f, 0.41f, projType, dmg, 0.0f, Main.myPlayer);
      Main.projectile[index].ai[0] = 1f;
      WorldGen.SquareTileFrame(i, j);
      WorldGen.ExploitDestroyQueue.Enqueue(new Point(i, j));
      WorldGen.ExploitDestroyQueue.Enqueue(new Point(i, j - 1));
    }
    if (Main.netMode == 2)
    {
      bool flag = false;
      for (int index = 0; index < 1000; ++index)
      {
        if (Main.projectile[index].active && Main.projectile[index].owner == Main.myPlayer && Main.projectile[index].type == projType && Math.Abs(Main.projectile[index].timeLeft - 3600) < 60 && (double) Main.projectile[index].Distance(new Vector2((float) (i * 16 /*0x10*/ + 8), (float) (j * 16 /*0x10*/ + 10))) < 4.0)
        {
          flag = true;
          break;
        }
      }
      if (!flag)
      {
        int index = Projectile.NewProjectile((IEntitySource) WorldGen.GetProjectileSource_TileBreak(i, j), (float) (i * 16 /*0x10*/ + 8), (float) (j * 16 /*0x10*/ + 8), 0.0f, 2.5f, projType, dmg, 0.0f, Main.myPlayer);
        Main.projectile[index].velocity.Y = 0.5f;
        Main.projectile[index].position.Y += 2f;
        Main.projectile[index].netUpdate = true;
      }
      WorldGen.SquareTileFrame(i, j);
      NetMessage.SendTileSquare(-1, i, j);
      WorldGen.ExploitDestroyQueue.Enqueue(new Point(i, j));
      WorldGen.ExploitDestroyQueue.Enqueue(new Point(i, j - 1));
    }
    return true;
  }

