    public readonly string Localization;
    private readonly string _code;
    private readonly LegacySoundStyle _sound;
    private string _plaintext;
    public string TextThatWasUsedToUnlock;
    private static int activeSecretSeedCount = 0;
    private bool _enabled;

    public static bool anySecretSeedIsActive => WorldGen.SecretSeed.activeSecretSeedCount > 0;

    public bool Enabled => this._enabled;

    private SecretSeed(string localization, LegacySoundStyle sound, string code)
    {
      this.Localization = localization;
      this._sound = sound;
      this._code = code;
    }

    public bool Check(string code)
    {
      if (string.IsNullOrWhiteSpace(code))
        return false;
      code = Regex.Replace(code.ToLower(), "[^a-z0-9]+", "");
      return !string.IsNullOrWhiteSpace(code) && this._code == Secrets.ToSecret(code);
    }

    public static WorldGen.SecretSeed Register(
      string localization,
      LegacySoundStyle sound,
      string code)
    {
      WorldGen.SecretSeed secretSeed = new WorldGen.SecretSeed(localization, sound, code);
      WorldGen.SecretSeed.AllSecretSeeds.Add(secretSeed);
      return secretSeed;
    }

    public static void ClearAllSeeds()
    {
      foreach (WorldGen.SecretSeed allSecretSeed in WorldGen.SecretSeed.AllSecretSeeds)
        WorldGen.SecretSeed.Disable(allSecretSeed);
    }

    public static bool CheckInputForSecretSeed(string worldSeed, out WorldGen.SecretSeed secretSeed)
    {
      string input = worldSeed;
      secretSeed = (WorldGen.SecretSeed) null;
      if (string.IsNullOrWhiteSpace(worldSeed))
        return false;
      worldSeed = Regex.Replace(worldSeed.ToLower(), "[^a-z0-9]+", "");
      if (string.IsNullOrWhiteSpace(worldSeed))
        return false;
      secretSeed = WorldGen.SecretSeed.AllSecretSeeds.FirstOrDefault<WorldGen.SecretSeed>((Func<WorldGen.SecretSeed, bool>) (s => s._plaintext == worldSeed));
      if (secretSeed == null)
      {
        string code = Secrets.ToSecret(worldSeed);
        secretSeed = WorldGen.SecretSeed.AllSecretSeeds.FirstOrDefault<WorldGen.SecretSeed>((Func<WorldGen.SecretSeed, bool>) (s => s._code == code));
      }
      if (secretSeed == null)
        return false;
      secretSeed._plaintext = worldSeed;
      string str = Regex.Replace(input, "[^a-zA-Z0-9 ]+", "");
      secretSeed.TextThatWasUsedToUnlock = str;
      return true;
    }

    public static void Enable(WorldGen.SecretSeed seed, bool playSound = true)
    {
      if (seed.Enabled)
        return;
      ++WorldGen.SecretSeed.activeSecretSeedCount;
      seed._enabled = true;
      if (!Main.dedServ)
        SecretSeedsTracker.AddSeedToTrack(seed.TextThatWasUsedToUnlock);
      if (!playSound)
        return;
      SoundEngine.PlaySound(seed._sound);
    }

    public static void Disable(WorldGen.SecretSeed seed)
    {
      if (!seed.Enabled)
        return;
      --WorldGen.SecretSeed.activeSecretSeedCount;
      seed._enabled = false;
    }

    public static bool GenerateBiggerAbandonedHouses
    {
      get
      {
        if (WorldGen.SecretSeed.biggerAbandonedHouses.Enabled)
          return true;
        return WorldGen.SecretSeed.errorWorld.Enabled && WorldGen.genRand.Next(3) == 0;
      }
    }

    public static bool GenerateRainbowGlowsticks
    {
      get => WorldGen.SecretSeed.rainbowStuff.Enabled || Main.tenthAnniversaryWorld;
    }

    public static void InitializeSecretSeeds()
    {
      if (WorldGen.SecretSeed.vampirism.Enabled)
        Main.vampireSeed = true;
      if (WorldGen.SecretSeed.worldIsInfected.Enabled)
        Main.infectedSeed = true;
      if (WorldGen.SecretSeed.teamBasedSpawns.Enabled)
        Main.teamBasedSpawnsSeed = true;
      if (WorldGen.SecretSeed.dualDungeons.Enabled)
        Main.dualDungeonsSeed = true;
      if (WorldGen.SecretSeed.endlessHalloween.Enabled)
        Main.forceHalloweenForever = true;
      if (!WorldGen.SecretSeed.endlessChristmas.Enabled)
        return;
      Main.forceXMasForever = true;
    }

    public static void FinalizeSecretSeeds()
    {
      if (WorldGen.SecretSeed.surfaceIsDesert.Enabled)
        WorldGen.SecretSeed.DoSurfaceIsDesertFinish();
      if (WorldGen.SecretSeed.extraLiquid.Enabled)
        WorldGen.SecretSeed.DoExtraLiquidFinish();
      if (WorldGen.SecretSeed.surfaceIsInSpace.Enabled)
        WorldGen.SecretSeed.DoSurfaceIsInSpace();
      if (WorldGen.SecretSeed.actuallyNoTraps.Enabled)
        WorldGen.SecretSeed.DoActuallyNoTraps();
      if (WorldGen.SecretSeed.surfaceIsMushrooms.Enabled)
      {
        if (!WorldGen.SecretSeed.noSurface.Enabled)
          WorldGen.SecretSeed.DoSurfaceIsMushrooms();
        WorldGen.SecretSeed.DoSurfaceIsMushrooms();
      }
      if (WorldGen.SecretSeed.worldIsFrozen.Enabled)
        WorldGen.SecretSeed.DoWorldIsFrozen();
      if (WorldGen.SecretSeed.noInfection.Enabled)
        WorldGen.SecretSeed.DoNoInfection();
      if (WorldGen.SecretSeed.hallowOnTheSurface.Enabled)
        WorldGen.SecretSeed.DoHallowOnSurface();
      if (WorldGen.SecretSeed.worldIsInfected.Enabled)
        WorldGen.SecretSeed.DoWorldIsInfected();
      if (WorldGen.SecretSeed.startInHardmode.Enabled)
        WorldGen.SecretSeed.DoStartInHardmode();
      if (WorldGen.SecretSeed.noSurface.Enabled)
        WorldGen.SecretSeed.DoNoSurface();
      if (WorldGen.SecretSeed.coatEverythingEcho.Enabled)
        WorldGen.SecretSeed.DoCoatEverythingEcho();
      if (WorldGen.SecretSeed.coatEverythingIlluminant.Enabled)
        WorldGen.SecretSeed.DoCoatEverythingIlluminant();
      if (WorldGen.SecretSeed.paintEverythingGray.Enabled)
        WorldGen.SecretSeed.DoPaintEverythingGray();
      if (WorldGen.SecretSeed.paintEverythingNegative.Enabled)
        WorldGen.SecretSeed.DoPaintEverythingNegative();
      if (WorldGen.SecretSeed.randomSpawn.Enabled)
        WorldGen.SecretSeed.DoRandomSpawn();
      if (WorldGen.SecretSeed.rainbowStuff.Enabled)
        WorldGen.SecretSeed.DoRainbowStuff();
      if (WorldGen.SecretSeed.portalGunInChests.Enabled)
        WorldGen.SecretSeed.DoPortalGunInChests();
      if (WorldGen.SecretSeed.worldIsFrozen.Enabled)
