        tile4.slope((byte) 0);
        tile4.halfBrick(false);
      }
      if (!tile5.active() || tile5.slope() != (byte) 0 || tile5.halfBrick())
      {
        if (!tile5.active())
        {
          tile5.type = type;
          tile5.active(true);
        }
        tile5.slope((byte) 0);
        tile5.halfBrick(false);
      }
      if (tile6.active() && tile6.slope() == (byte) 0 && !tile6.halfBrick())
        return;
      if (!tile6.active())
      {
        tile6.type = type;
