    public static void Calculate()
    {
      WorldGen.Skyblock.noAltars = true;
      WorldGen.Skyblock.noDungeon = true;
      WorldGen.Skyblock.noTemple = true;
      WorldGen.Skyblock.noHellstone = true;
      WorldGen.Skyblock.noFossils = true;
      WorldGen.Skyblock.noLifeCrystals = true;
      WorldGen.Skyblock.noHellforge = true;
      for (int index = 0; index < (int) TileID.Count; ++index)
      {
        if (WorldGen.Skyblock.hasTile[index])
        {
          if (Main.tileDungeon[index])
            WorldGen.Skyblock.noDungeon = false;
          if (index == 26)
            WorldGen.Skyblock.noAltars = false;
          if (index == 226)
            WorldGen.Skyblock.noTemple = false;
          if (index == 58)
            WorldGen.Skyblock.noHellstone = false;
          if (index == 404)
            WorldGen.Skyblock.noFossils = false;
          if (index == 12)
            WorldGen.Skyblock.noLifeCrystals = false;
          if (index == 77)
            WorldGen.Skyblock.noHellforge = false;
          if (index == 133)
            WorldGen.Skyblock.noHellforge = false;
        }
      }
      for (int index = 0; index < (int) WallID.Count; ++index)
      {
        if (WorldGen.Skyblock.hasWall[index])
        {
          if (Main.wallDungeon[index])
            WorldGen.Skyblock.noDungeon = false;
          if (index == 87)
            WorldGen.Skyblock.noTemple = false;
        }
      }
      int num1 = Main.maxTilesX * Main.maxTilesY;
      double num2 = (double) WorldGen.Skyblock.currentActiveTiles / (double) num1;
      WorldGen.Skyblock.currentActiveTiles = 0;
      bool lowTiles = WorldGen.Skyblock.lowTiles;
      WorldGen.Skyblock.lowTiles = false;
      if (num2 < 0.10000000149011612 && Main.skyblockWorld)
        WorldGen.Skyblock.lowTiles = true;
      for (int index = 0; index < (int) TileID.Count; ++index)
        WorldGen.Skyblock.hasTile[index] = false;
      for (int index = 0; index < (int) WallID.Count; ++index)
        WorldGen.Skyblock.hasWall[index] = false;
      if (WorldGen.Skyblock.noDungeon)
      {
        Main.dungeonX = -1;
        Main.dungeonY = -1;
      }
      if (WorldGen.Skyblock.lowTiles == lowTiles)
        return;
      NetMessage.SendData(7);
    }

    public static void ScanTiles()
    {
      WorldGen.Skyblock.currentActiveTiles = 0;
      for (int index = 0; index < (int) TileID.Count; ++index)
        WorldGen.Skyblock.hasTile[index] = false;
      for (int index = 0; index < (int) WallID.Count; ++index)
        WorldGen.Skyblock.hasWall[index] = false;
      int num1 = Main.maxTilesX - 40;
      int num2 = 40;
      int num3 = Main.maxTilesY - 40;
      for (int index1 = 40; index1 < num1; ++index1)
      {
        for (int index2 = num2; index2 < num3; ++index2)
        {
          if (Main.tile[index1, index2].active())
          {
            ++WorldGen.Skyblock.currentActiveTiles;
            WorldGen.Skyblock.hasTile[(int) Main.tile[index1, index2].type] = true;
          }
          WorldGen.Skyblock.hasWall[(int) Main.tile[index1, index2].wall] = true;
        }
      }
      WorldGen.Skyblock.Calculate();
    }
  }

